/* DAWAH X — darimi, অধ্যায় 4 · খণ্ড 4 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][4]=[[601,601,"","","‏ ‏أَخْبَرَنَا ‏ ‏قَبِيصَةُ ‏ ‏وَمُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏تَذَاكَرُوا الْحَدِيثَ فَإِنَّ ذِكْرَهُ حَيَاتُهُ ‏","","",""],[602,602,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ قُدَامَةَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏يُحَدِّثُ الْأَعْرَابَ ‏","","",""],[603,603,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏إِسْمَعِيلُ بْنُ رَجَاءٍ ‏ ‏يَجْمَعُ صِبْيَانَ الْكُتَّابِ يُحَدِّثُهُمْ يَتَحَفَّظُ بِذَاكَ ‏","","",""],[604,604,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الشَّقَرِيِّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏حَدِّثْ حَدِيثَكَ مَنْ ‏ ‏يَشْتَهِيهِ وَمَنْ لَا ‏ ‏يَشْتَهِيهِ فَإِنَّهُ يَصِيرُ عِنْدَكَ كَأَنَّهُ إِمَامٌ تَقْرَؤُهُ ‏","","",""],[605,605,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏وَمُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ السَّلَامِ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ مِنَّا حَدِيثًا فَتَذَاكَرُوهُ بَيْنَكُمْ ‏","","",""],[606,606,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هُشَيْمٍ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ ‏ ‏كُنَّا نَأْتِي ‏ ‏الْحَسَنَ ‏ ‏فَإِذَا خَرَجْنَا مِنْ عِنْدِهِ تَذَاكَرْنَا بَيْنَنَا ‏","","",""],[607,607,"","","‏ ‏أَخْبَرَنَا ‏ ‏صَدَقَةُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حُنَيْنِ بْنِ أَبِي حَكِيمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَرْوِيَ حَدِيثًا فَلْيُرَدِّدْهُ ثَلَاثًا ‏","","",""],[608,608,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏إِحْيَاءُ الْحَدِيثِ مُذَاكَرَتُهُ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏يَرْحَمُكَ اللَّهُ كَمْ مِنْ حَدِيثٍ أَحْيَيْتَهُ فِي صَدْرِي كَانَ قَدْ مَاتَ ‏","","",""],[609,609,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْحَارِثُ بْنُ يَزِيدَ الْعُكْلِيُّ ‏ ‏وَابْنُ شُبْرُمَةَ ‏ ‏وَالْقَعْقَاعُ بْنُ يَزِيدَ ‏ ‏وَمُغِيرَةُ ‏ ‏إِذَا صَلَّوْا الْعِشَاءَ الْآخِرَةَ جَلَسُوا فِي الْفِقْهِ فَلَمْ يُفَرِّقْ بَيْنَهُمْ إِلَّا أَذَانُ الصُّبْحِ ‏","","",""],[610,610,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَرِيكًا ‏ ‏ذَكَرَ عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَطَاوُسٍ ‏ ‏وَمُجَاهِدٍ ‏ ‏قَالَ ‏ ‏عَنْ اثْنَيْنِ مِنْهُمْ لَا بَأْسَ بِالسَّمَرِ فِي الْفِقْهِ ‏","","",""],[611,611,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏لَا بَأْسَ بِالسَّمَرِ فِي الْفِقْهِ ‏","","",""],[612,612,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏تَدَارُسُ الْعِلْمِ سَاعَةً مِنْ اللَّيْلِ خَيْرٌ مِنْ ‏ ‏إِحْيَائِهَا ‏","","",""],[613,613,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏وَمُحَمَّدُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏هُشَيْمٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏كُنَّا نَأْتِي ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَإِذَا خَرَجْنَا مِنْ عِنْدِهِ تَذَاكَرْنَا فَكَانَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَحْفَظَنَا لِحَدِيثِهِ ‏","","",""],[614,614,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏اللَّيْثَ بْنَ سَعْدٍ ‏ ‏يَقُولُ ‏ ‏تَذَاكَرَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏لَيْلَةً بَعْدَ الْعِشَاءِ حَدِيثًا وَهُوَ جَالِسٌ مُتَوَضِّئًا ‏ ‏قَالَ ‏ ‏فَمَا زَالَ ذَلِكَ مَجْلِسَهُ حَتَّى أَصْبَحَ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏جَعَلَ يَتَذَاكَرُ الْحَدِيثَ ‏","","",""],[615,615,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏إِذَا لَقِيتُ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏فَكَأَنَّمَا أَفْجُرُ بِهِ بَحْرًا ‏","","",""],[616,616,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْحَارِثُ الْعُكْلِيُّ ‏ ‏وَأَصْحَابُهُ يَتَجَالَسُونَ بِاللَّيْلِ وَيَذْكُرُونَ الْفِقْهَ ‏","","",""],[617,617,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَذَاكَرُوا هَذَا الْحَدِيثَ فَإِنَّ حَيَاتَهُ مُذَاكَرَتُهُ ‏","","",""],[618,618,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَوْنٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لِأَصْحَابِهِ حِينَ قَدِمُوا عَلَيْهِ ‏ ‏هَلْ ‏ ‏تَجَالَسُونَ قَالُوا لَيْسَ نُتْرَكُ وَذَاكَ قَالَ فَهَلْ ‏ ‏تَزَاوَرُونَ قَالُوا نَعَمْ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّ الرَّجُلَ مِنَّا لَيَفْقِدُ أَخَاهُ فَيَمْشِي فِي طَلَبِهِ إِلَى أَقْصَى ‏ ‏الْكُوفَةِ ‏ ‏حَتَّى يَلْقَاهُ قَالَ فَإِنَّكُمْ لَنْ تَزَالُوا بِخَيْرٍ مَا فَعَلْتُمْ ذَلِكَ ‏","","",""],[619,619,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏آفَةُ الْعِلْمِ النِّسْيَانُ وَتَرْكُ الْمُذَاكَرَةِ ‏","","",""],[620,620,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏آفَةُ الْحَدِيثِ النِّسْيَانُ ‏","","",""],[621,621,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏طَارِقٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جَابِرٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ لِكُلِّ شَيْءٍ آفَةً وَآفَةُ الْعِلْمِ النِّسْيَانُ ‏","","",""],[622,622,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آفَةُ الْعِلْمِ النِّسْيَانُ وَإِضَاعَتُهُ أَنْ تُحَدِّثَ بِهِ غَيْرَ أَهْلِهِ ‏","","",""],[623,623,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو حَمْزَةَ الثُّمَالِيُّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏غَائِلَةُ ‏ ‏الْعِلْمِ النِّسْيَانُ ‏","","",""],[624,624,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏تَذَاكَرُوا هَذَا الْحَدِيثَ وَتَزَاوَرُوا فَإِنَّكُمْ إِنْ لَمْ تَفْعَلُوا ‏ ‏يَدْرُسْ ‏","","",""],[625,625,"","","‏ ‏أَخْبَرَنَا ‏ ‏بِشْرُ بْنُ الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُفْيَانَ ‏ ‏يَقُولُ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏كُنْتُ ‏ ‏أَحْسَبُ بِأَنِّي أَصَبْتُ مِنْ الْعِلْمِ فَجَالَسْتُ ‏ ‏عُبَيْدَ اللَّهِ ‏ ‏فَكَأَنِّي كُنْتُ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏","","",""],[626,626,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ قِيلَ ‏ ‏لِعُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏لَوْ جَمَعْتَ النَّاسَ عَلَى شَيْءٍ فَقَالَ مَا يَسُرُّنِي أَنَّهُمْ لَمْ يَخْتَلِفُوا قَالَ ثُمَّ كَتَبَ إِلَى الْآفَاقِ وَإِلَى الْأَمْصَارِ لِيَقْضِ كُلُّ قَوْمٍ بِمَا اجْتَمَعَ عَلَيْهِ فُقَهَاؤُهُمْ ‏","","",""],[627,627,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا أُحِبُّ أَنَّ أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَخْتَلِفُوا فَإِنَّهُمْ لَوْ اجْتَمَعُوا عَلَى شَيْءٍ فَتَرَكَهُ رَجُلٌ تَرَكَ السُّنَّةَ وَلَوْ اخْتَلَفُوا فَأَخَذَ رَجُلٌ بِقَوْلِ أَحَدٍ أَخَذَ بِالسُّنَّةِ ‏","","",""],[628,628,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏رُبَّمَا رَأَى ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏الرَّأْيَ ثُمَّ تَرَكَهُ ‏","","",""],[629,629,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ الْمِنْهَالِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏قَالَ قَالَ لِي ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏إِنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ لِي ‏ ‏إِنِّي قَدْ رَأَيْتُ فِي الْجَدِّ رَأْيًا فَإِنْ رَأَيْتُمْ أَنْ تَتَّبِعُوهُ فَاتَّبِعُوهُ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏إِنْ نَتَّبِعْ رَأْيَكَ فَإِنَّهُ رَشَدٌ وَإِنْ نَتَّبِعْ رَأْيَ الشَّيْخِ قَبْلَكَ فَنِعْمَ ذُو الرَّأْيِ كَانَ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَجْعَلُهُ أَبًا ‏","","",""],[630,630,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ الْحِزَامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏قَالَ ‏ ‏عَرَضْتُ عَلَى ‏ ‏الشَّعْبِيِّ ‏ ‏أَحَادِيثَ الْفِقْهِ فَأَجَازَهَا لِي ‏","","",""],[631,631,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَمْرِو بْنِ دِينَارٍ ‏ ‏أَسَمِعْتَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ مَرَّ فِي الْمَسْجِدِ بِسِهَامٍ ‏ ‏أَمْسِكْ بِنِصَالِهَا قَالَ نَعَمْ ‏","","",""],[632,632,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏أَسَمِعْتَ ‏ ‏أَبَاكَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُهَا وَهُوَ صَائِمٌ قَالَ نَعَمْ ‏","","",""],[633,633,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَسَنُ بْنُ أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْكِينُ بْنُ بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏مَنْصُورٌ ‏ ‏بِحَدِيثٍ فَلَقِيتُهُ فَقُلْتُ ‏ ‏أُحَدِّثُ بِهِ عَنْكَ قَالَ ‏ ‏أَوَ لَيْسَ إِذَا كَتَبْتُ إِلَيْكَ فَقَدْ حَدَّثْتُكَ ‏ ‏قَالَ ‏ ‏وَسَأَلْتُ ‏ ‏أَيُّوبَ السَّخْتِيَانِيَّ ‏ ‏فَقَالَ مِثْلَ ذَلِكَ ‏","","",""],[634,634,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏عَرَضْتُ عَلَيْهِ كِتَابًا فَقُلْتُ ‏ ‏أَرْوِيهِ عَنْكَ قَالَ وَمَنْ حَدَّثَكَ بِهِ غَيْرِي ‏","","",""],[635,635,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ الْحِزَامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَطَاءٍ ‏ ‏مَوْلَى ‏ ‏الْمُزَنِيِّينَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عَرْضُ الْكِتَابِ وَالْحَدِيثُ سَوَاءٌ ‏","","",""],[636,636,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عَرْضُ الْكِتَابِ وَالْحَدِيثُ سَوَاءٌ ‏","","",""],[637,637,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَطَاءٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏يَرَى عَرْضَ الْكِتَابِ وَالْحَدِيثَ سَوَاءً ‏ ‏وَكَانَ ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏يَرَى ذَلِكَ ‏","","",""],[638,638,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَرَى الْعَرْضَ وَالْحَدِيثَ سَوَاءً ‏","","",""],[639,639,"","","‏ ‏أَخْبَرَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏إِبْرَاهِيمُ ‏ ‏يَقُولُ يَقُومُ عَنْ يَسَارِهِ ‏ ‏فَحَدَّثْتُهُ عَنْ ‏ ‏سُمَيْعٍ الزَّيَّاتِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَامَهُ عَنْ يَمِينِهِ فَأَخَذَ بِهِ ‏","","",""],[640,640,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عَنْبَسَةَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ زَيْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَقَّارِ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏نَشَدَ ‏ ‏عُمَرُ ‏ ‏النَّاسَ أَسَمِعَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدٌ مِنْكُمْ فِي الْجَنِينِ فَقَامَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَقَالَ قَضَى فِيهِ عَبْدًا أَوْ أَمَةً ‏ ‏فَنَشَدَ ‏ ‏النَّاسَ أَيْضًا فَقَامَ ‏ ‏الْمَقْضِيُّ لَهُ ‏ ‏فَقَالَ ‏ ‏قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِي بِهِ عَبْدًا أَوْ أَمَةً ‏ ‏فَنَشَدَ ‏ ‏النَّاسَ أَيْضًا فَقَامَ الْمَقْضِيُّ عَلَيْهِ فَقَالَ قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيَّ ‏ ‏غُرَّةً ‏ ‏عَبْدًا أَوْ أَمَةً فَقُلْتُ ‏ ‏أَتَقْضِي عَلَيَّ فِيهِ فِيمَا لَا أَكَلَ وَلَا شَرِبَ وَلَا ‏ ‏اسْتَهَلَّ ‏ ‏وَلَا نَطَقَ أَنْ ‏ ‏تُطِلَّهُ ‏ ‏فَهُوَ أَحَقُّ مَا يُطَلُّ فَهَمَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ بِشَيْءٍ مَعَهُ فَقَالَ ‏ ‏أَشِعْرٌ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَوْلَا مَا بَلَغَنِي مِنْ قَضَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَجَعَلْتُهُ دِيَةً بَيْنَ دِيَتَيْنِ ‏","","",""],[641,641,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏قَالَ كَانَ ‏ ‏سَلَّامٌ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ ‏ ‏إِذَا أَرَدْتَ أَنْ تَعْرِفَ خَطَأَ مُعَلِّمِكَ فَجَالِسْ غَيْرَهُ ‏","","",""],[642,642,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا ‏ ‏بِمَكَّةَ ‏ ‏الرَّجُلَ يَمُوتُ فَقُلْتُ ‏ ‏عِدَّتُهَا مِنْ يَوْمِ يَأْتِيهَا الْخَبَرُ ‏ ‏لِقَوْلِ ‏ ‏الْحَسَنِ ‏ ‏وَقَتَادَةَ ‏ ‏وَأَصْحَابِنَا ‏ ‏قَالَ ‏ ‏فَلَقِيَنِي ‏ ‏طَلْقُ بْنُ حَبِيبٍ الْعَنَزِيُّ ‏ ‏فَقَالَ ‏ ‏إِنَّكَ عَلَيَّ كَرِيمٌ وَإِنَّكَ مِنْ أَهْلِ بَلَدٍ الْعَيْنُ إِلَيْهِمْ سَرِيعَةٌ وَإِنِّي لَسْتُ آمَنُ عَلَيْكَ وَإِنَّكَ قُلْتَ قَوْلًا هَا هُنَا خِلَافَ قَوْلِ أَهْلِ الْبَلَدِ وَلَسْتُ آمَنُ فَقُلْتُ وَفِي ذَا اخْتِلَافٌ قَالَ نَعَمْ عِدَّتُهَا مِنْ يَوْمِ يَمُوتُ ‏ ‏فَلَقِيتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏فَسَأَلْتُهُ ‏ ‏فَقَالَ ‏ ‏عِدَّتُهَا مِنْ يَوْمِ تُوُفِّيَ ‏ ‏قَالَ وَسَأَلْتُ ‏ ‏مُجَاهِدًا ‏ ‏فَقَالَ ‏ ‏عِدَّتُهَا مِنْ يَوْمِ تُوُفِّيَ ‏ ‏وَسَأَلْتُ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏فَقَالَ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏وَسَأَلْتُ ‏ ‏أَبَا قِلَابَةَ ‏ ‏فَقَالَ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏وَسَأَلْتُ ‏ ‏مُحَمَّدَ بْنَ سِيرِينَ ‏ ‏فَقَالَ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏وَحَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏و سَمِعْت ‏ ‏عِكْرِمَةَ ‏ ‏يَقُولُ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏جَابِرُ بْنُ زَيْدٍ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَسَمِعْتُ ‏ ‏لَيْثًا ‏ ‏حَدَّثَ عَنْ ‏ ‏الْحَكَمِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏مِنْ يَوْمِ تُوُفِّيَ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ ‏ ‏عَلِيٌّ ‏ ‏مِنْ يَوْمِ يَأْتِيهَا الْخَبَرُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَقُولُ مِنْ يَوْمِ تُوُفِّيَ ‏","","",""],[643,643,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏عُمَرَ ‏ ‏فِي ‏ ‏الْمُشَرَّكَةِ ‏ ‏فَلَمْ ‏ ‏يُشَرِّكْ ‏ ‏ثُمَّ أَتَيْنَاهُ الْعَامَ الْمُقْبِلَ ‏ ‏فَشَرَّكَ ‏ ‏فَقُلْنَا لَهُ فَقَالَ تِلْكَ عَلَى مَا قَضَيْنَا وَهَذِهِ عَلَى مَا قَضَيْنَا ‏","","",""],[644,644,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الْأَسْوَدُ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مُنَبِّهٍ ‏ ‏كَانَ أَهْلُ الْعِلْمِ فِيمَا مَضَى ‏ ‏يَضَنُّونَ ‏ ‏بِعِلْمِهِمْ عَنْ أَهْلِ الدُّنْيَا فَيَرْغَبُ أَهْلُ الدُّنْيَا فِي عِلْمِهِمْ فَيَبْذُلُونَ لَهُمْ دُنْيَاهُمْ وَإِنَّ أَهْلَ الْعِلْمِ الْيَوْمَ بَذَلُوا عِلْمَهُمْ لِأَهْلِ الدُّنْيَا فَزَهِدَ أَهْلُ الدُّنْيَا فِي عِلْمِهِمْ ‏ ‏فَضَنُّوا ‏ ‏عَلَيْهِمْ بِدُنْيَاهُمْ ‏","","",""],[645,645,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُمَرَ بْنِ الْكُمَيْتِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ وَهْبٍ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مُوسَى ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏سُلَيْمَانُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَهُوَ يُرِيدُ ‏ ‏مَكَّةَ ‏ ‏فَأَقَامَ بِهَا أَيَّامًا فَقَالَ هَلْ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَحَدٌ أَدْرَكَ أَحَدًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا لَهُ ‏ ‏أَبُو حَازِمٍ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ فَأَرْسَلَ إِلَيْهِ فَلَمَّا دَخَلَ عَلَيْهِ قَالَ لَهُ يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏مَا هَذَا ‏ ‏الْجَفَاءُ ‏ ‏قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏وَأَيُّ ‏ ‏جَفَاءٍ ‏ ‏رَأَيْتَ مِنِّي قَالَ أَتَانِي وُجُوهُ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏وَلَمْ تَأْتِنِي قَالَ يَا أَمِيرَ الْمُؤْمِنِينَ أُعِيذُكَ بِاللَّهِ أَنْ تَقُولَ مَا لَمْ يَكُنْ مَا عَرَفْتَنِي قَبْلَ هَذَا الْيَوْمِ وَلَا أَنَا رَأَيْتُكَ قَالَ فَالْتَفَتَ ‏ ‏سُلَيْمَانُ ‏ ‏إِلَى ‏ ‏مُحَمَّدِ بْنِ شِهَابٍ الزُّهْرِيِّ ‏ ‏فَقَالَ أَصَابَ الشَّيْخُ وَأَخْطَأْتُ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏مَا لَنَا نَكْرَهُ الْمَوْتَ قَالَ لِأَنَّكُمْ أَخْرَبْتُمْ الْآخِرَةَ وَعَمَّرْتُمْ الدُّنْيَا فَكَرِهْتُمْ أَنْ تُنْقَلُوا مِنْ الْعُمْرَانِ إِلَى الْخَرَابِ قَالَ أَصَبْتَ يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏فَكَيْفَ الْقُدُومُ غَدًا عَلَى اللَّهِ قَالَ أَمَّا الْمُحْسِنُ فَكَالْغَائِبِ يَقْدُمُ عَلَى أَهْلِهِ وَأَمَّا الْمُسِيءُ ‏ ‏فَكَالْآبِقِ ‏ ‏يَقْدُمُ عَلَى مَوْلَاهُ فَبَكَى ‏ ‏سُلَيْمَانُ ‏ ‏وَقَالَ لَيْتَ شِعْرِي مَا لَنَا عِنْدَ اللَّهِ قَالَ اعْرِضْ عَمَلَكَ عَلَى كِتَابِ اللَّهِ قَالَ وَأَيُّ مَكَانٍ أَجِدُهُ قَالَ ‏ { ‏إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ ‏} ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَأَيْنَ رَحْمَةُ اللَّهِ يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏قَالَ ‏ ‏أَبُو حَازِمٍ ‏ { ‏رَحْمَةَ اللَّهِ قَرِيبٌ مِنْ الْمُحْسِنِينَ ‏} ‏قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏فَأَيُّ عِبَادِ اللَّهِ أَكْرَمُ قَالَ أُولُو الْمُرُوءَةِ ‏ ‏وَالنُّهَى ‏ ‏قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏فَأَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏أَدَاءُ الْفَرَائِضِ مَعَ اجْتِنَابِ الْمَحَارِمِ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَأَيُّ الدُّعَاءِ أَسْمَعُ قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏دُعَاءُ الْمُحْسَنِ إِلَيْهِ لِلْمُحْسِنِ قَالَ فَأَيُّ الصَّدَقَةِ أَفْضَلُ قَالَ لِلسَّائِلِ الْبَائِسِ وَجُهْدُ ‏ ‏الْمُقِلِّ ‏ ‏لَيْسَ فِيهَا ‏ ‏مَنٌّ ‏ ‏وَلَا أَذًى قَالَ فَأَيُّ الْقَوْلِ أَعْدَلُ قَالَ قَوْلُ الْحَقِّ عِنْدَ مَنْ تَخَافُهُ أَوْ ‏ ‏تَرْجُوهُ قَالَ فَأَيُّ الْمُؤْمِنِينَ ‏ ‏أَكْيَسُ ‏ ‏قَالَ رَجُلٌ عَمِلَ بِطَاعَةِ اللَّهِ وَدَلَّ النَّاسَ عَلَيْهَا قَالَ فَأَيُّ الْمُؤْمِنِينَ أَحْمَقُ قَالَ رَجُلٌ انْحَطَّ فِي هَوَى أَخِيهِ وَهُوَ ظَالِمٌ فَبَاعَ آخِرَتَهُ بِدُنْيَا غَيْرِهِ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏أَصَبْتَ فَمَا تَقُولُ فِيمَا نَحْنُ فِيهِ قَالَ يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏أَوَ ‏ ‏تُعْفِينِي قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏لَا وَلَكِنْ نَصِيحَةٌ ‏ ‏تُلْقِيهَا إِلَيَّ قَالَ يَا أَمِيرَ الْمُؤْمِنِينَ إِنَّ آبَاءَكَ قَهَرُوا النَّاسَ بِالسَّيْفِ وَأَخَذُوا هَذَا الْمُلْكَ ‏ ‏عَنْوَةً ‏ ‏عَلَى غَيْرِ مَشُورَةٍ مِنْ الْمُسْلِمِينَ وَلَا رِضَاهُمْ حَتَّى قَتَلُوا مِنْهُمْ مَقْتَلَةً عَظِيمَةً فَقَدْ ارْتَحَلُوا عَنْهَا فَلَوْ أُشْعِرْتَ مَا قَالُوا وَمَا قِيلَ لَهُمْ فَقَالَ لَهُ رَجُلٌ مِنْ جُلَسَائِهِ بِئْسَ مَا قُلْتَ يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏كَذَبْتَ إِنَّ اللَّهَ أَخَذَ مِيثَاقَ الْعُلَمَاءِ لَيُبَيِّنُنَّهُ لِلنَّاسِ وَلَا يَكْتُمُونَهُ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏فَكَيْفَ لَنَا أَنْ نُصْلِحَ قَالَ تَدَعُونَ ‏ ‏الصَّلَفَ ‏ ‏وَتَمَسَّكُونَ بِالْمُرُوءَةِ وَتَقْسِمُونَ بِالسَّوِيَّةِ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏كَيْفَ لَنَا بِالْمَأْخَذِ بِهِ قَالَ ‏ ‏أَبُو حَاَزِمٍ ‏ ‏تَأْخُذُهُ مِنْ حِلِّهِ وَتَضَعُهُ فِي أَهْلِهِ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏هَلْ لَكَ يَا ‏ ‏أَبَا حَازِمٍ ‏ ‏أَنْ تَصْحَبَنَا فَتُصِيبَ مِنَّا وَنُصِيبَ مِنْكَ قَالَ أَعُوذُ بِاللَّهِ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏وَلِمَ ذَاكَ قَالَ ‏ ‏أَخْشَى أَنْ أَرْكَنَ إِلَيْكُمْ شَيْئًا قَلِيلًا فَيُذِيقَنِي اللَّهُ ضِعْفَ الْحَيَاةِ وَضِعْفَ الْمَمَاتِ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏ارْفَعْ إِلَيْنَا حَوَائِجَكَ قَالَ ‏ ‏تُنْجِينِي مِنْ النَّارِ وَتُدْخِلُنِي الْجَنَّةَ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏لَيْسَ ذَاكَ إِلَيَّ قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏فَمَا لِي إِلَيْكَ حَاجَةٌ غَيْرُهَا قَالَ فَادْعُ لِي قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏اللَّهُمَّ إِنْ كَانَ ‏ ‏سُلَيْمَانُ ‏ ‏وَلِيَّكَ فَيَسِّرْهُ لِخَيْرِ الدُّنْيَا وَالْآخِرَةِ وَإِنْ كَانَ عَدُوَّكَ فَخُذْ بِنَاصِيَتِهِ إِلَى مَا تُحِبُّ ‏ ‏وَتَرْضَى قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏قَطُّ قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏قَدْ أَوْجَزْتُ وَأَكْثَرْتُ إِنْ كُنْتَ مِنْ أَهْلِهِ وَإِنْ لَمْ تَكُنْ مِنْ أَهْلِهِ فَمَا يَنْفَعُنِي أَنْ أَرْمِيَ عَنْ قَوْسٍ لَيْسَ لَهَا وَتَرٌ قَالَ لَهُ ‏ ‏سُلَيْمَانُ ‏ ‏أَوْصِنِي قَالَ ‏ ‏سَأُوصِيكَ وَأُوجِزُ عَظِّمْ رَبَّكَ ‏ ‏وَنَزِّهْهُ أَنْ يَرَاكَ حَيْثُ نَهَاكَ أَوْ يَفْقِدَكَ حَيْثُ أَمَرَكَ فَلَمَّا خَرَجَ مِنْ عِنْدِهِ بَعَثَ إِلَيْهِ بِمِائَةِ دِينَارٍ وَكَتَبَ إِلَيْهِ أَنْ أَنْفِقْهَا وَلَكَ عِنْدِي مِثْلُهَا كَثِيرٌ قَالَ فَرَدَّهَا عَلَيْهِ وَكَتَبَ إِلَيْهِ يَا أَمِيرَ الْمُؤْمِنِينَ أُعِيذُكَ بِاللَّهِ أَنْ يَكُونَ سُؤَالُكَ إِيَّايَ هَزْلًا أَوْ رَدِّي عَلَيْكَ بَذْلًا وَمَا أَرْضَاهَا لَكَ فَكَيْفَ أَرْضَاهَا لِنَفْسِي وَكَتَبَ إِلَيْهِ إِنَّ ‏ ‏مُوسَى بْنَ عِمْرَانَ ‏ ‏لَمَّا وَرَدَ مَاءَ ‏ ‏مَدْيَنَ ‏ ‏وَجَدَ عَلَيْهَا رِعَاءً يَسْقُونَ وَوَجَدَ مِنْ دُونِهِمْ جَارِيَتَيْنِ ‏ ‏تَذُودَانِ ‏ ‏فَسَأَلَهُمَا فَقَالَتَا ‏ { ‏لَا نَسْقِي حَتَّى ‏ ‏يُصْدِرَ ‏ ‏الرِّعَاءُ ‏ ‏وَأَبُونَا شَيْخٌ كَبِيرٌ فَسَقَى لَهُمَا ثُمَّ تَوَلَّى إِلَى الظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ ‏} ‏وَذَلِكَ أَنَّهُ كَانَ جَائِعًا خَائِفًا لَا يَأْمَنُ فَسَأَلَ رَبَّهُ وَلَمْ يَسْأَلْ النَّاسَ فَلَمْ يَفْطِنْ الرِّعَاءُ وَفَطِنَتْ الْجَارِيتَانِ فَلَمَّا رَجَعَتَا إِلَى أَبِيهِمَا أَخْبَرَتَاهُ بِالْقِصَّةِ وَبِقَوْلِهِ فَقَالَ أَبُوهُمَا ‏ ‏وَهُوَ ‏ ‏شُعَيْبٌ ‏ ‏هَذَا رَجُلٌ جَائِعٌ فَقَالَ لِإِحْدَاهُمَا اذْهَبِي فَادْعِيهِ فَلَمَّا أَتَتْهُ عَظَّمَتْهُ وَغَطَّتْ وَجْهَهَا وَقَالَتْ ‏ { ‏إِنَّ أَبِي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا ‏} ‏فَشَقَّ عَلَى ‏ ‏مُوسَى ‏ ‏حِينَ ذَكَرَتْ ‏ { ‏أَجْرَ مَا سَقَيْتَ لَنَا ‏} ‏وَلَمْ يَجِدْ بُدًّا مِنْ أَنْ يَتْبَعَهَا إِنَّهُ كَانَ بَيْنَ الْجِبَالِ جَائِعًا مُسْتَوْحِشًا فَلَمَّا تَبِعَهَا هَبَّتْ الرِّيحُ فَجَعَلَتْ ‏ ‏تَصْفِقُ ‏ ‏ثِيَابَهَا عَلَى ظَهْرِهَا فَتَصِفُ لَهُ ‏ ‏عَجِيزَتَهَا ‏ ‏وَكَانَتْ ذَاتَ ‏ ‏عَجُزٍ ‏ ‏وَجَعَلَ ‏ ‏مُوسَى ‏ ‏يُعْرِضُ مَرَّةً وَيَغُضُّ أُخْرَى فَلَمَّا ‏ ‏عِيلَ ‏ ‏صَبْرُهُ نَادَاهَا يَا أَمَةَ اللَّهِ كُونِي خَلْفِي وَأَرِينِي ‏ ‏السَّمْتَ ‏ ‏بِقَوْلِكِ ذَا فَلَمَّا دَخَلَ عَلَى ‏ ‏شُعَيْبٍ ‏ ‏إِذَا هُوَ بِالْعَشَاءِ مُهَيَّأً فَقَالَ لَهُ ‏ ‏شُعَيْبٌ ‏ ‏اجْلِسْ يَا شَابُّ فَتَعَشَّ فَقَالَ لَهُ ‏ ‏مُوسَى ‏ ‏أَعُوذُ بِاللَّهِ فَقَالَ لَهُ ‏ ‏شُعَيْبٌ ‏ ‏لِمَ أَمَا أَنْتَ جَائِعٌ قَالَ بَلَى وَلَكِنِّي أَخَافُ أَنْ يَكُونَ هَذَا عِوَضًا لِمَا سَقَيْتُ لَهُمَا وَإِنَّا مِنْ أَهْلِ بَيْتٍ لَا نَبِيعُ شَيْئًا مِنْ دِينِنَا بِمِلْءِ الْأَرْضِ ذَهَبًا فَقَالَ لَهُ ‏ ‏شُعَيْبٌ ‏ ‏لَا يَا شَابُّ وَلَكِنَّهَا عَادَتِي وَعَادَةُ آبَائِي ‏ ‏نُقْرِي ‏ ‏الضَّيْفَ وَنُطْعِمُ الطَّعَامَ فَجَلَسَ ‏ ‏مُوسَى ‏ ‏فَأَكَلَ فَإِنْ كَانَتْ هَذِهِ الْمِائَةُ دِينَارٍ عِوَضًا لِمَا حَدَّثْتُ ‏ ‏فَالْمَيْتَةُ ‏ ‏وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ فِي حَالِ ‏ ‏الِاضْطِرَارِ أَحَلُّ مِنْ هَذِهِ وَإِنْ كَانَ لِحَقٍّ لِي فِي بَيْتِ الْمَالِ فَلِي فِيهَا ‏ ‏نُظَرَاءُ ‏ ‏فَإِنْ سَاوَيْتَ بَيْنَنَا وَإِلَّا فَلَيْسَ لِي فِيهَا حَاجَةٌ ‏","","",""],[646,646,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عُثْمَانَ الْبَصْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُسْلِمٍ الْقَسْمَلِيِّ ‏ ‏أَخْبَرَنَا ‏ ‏زَيْدٌ الْعَمِّيُّ ‏ ‏عَنْ ‏ ‏بَعْضِ الْفُقَهَاءِ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا صَاحِبَ الْعِلْمِ اعْمَلْ بِعِلْمِكَ وَأَعْطِ ‏ ‏فَضْلَ ‏ ‏مَالِكَ وَاحْبِسْ ‏ ‏الْفَضْلَ ‏ ‏مِنْ قَوْلِكَ إِلَّا بِشَيْءٍ مِنْ الْحَدِيثِ يَنْفَعُكَ عِنْدَ رَبِّكَ يَا صَاحِبَ الْعِلْمِ إِنَّ الَّذِي عَلِمْتَ ثُمَّ لَمْ تَعْمَلْ بِهِ قَاطِعٌ حُجَّتَكَ وَمَعْذِرَتَكَ عِنْدِ رَبِّكَ إِذَا لَقِيتَهُ يَا صَاحِبَ الْعِلْمِ إِنَّ الَّذِي أُمِرْتَ بِهِ مِنْ طَاعَةِ اللَّهِ لَيَشْغَلُكَ عَمَّا نُهِيتَ عَنْهُ مِنْ مَعْصِيَةِ اللَّهِ يَا صَاحِبَ الْعِلْمِ لَا تَكُونَنَّ قَوِيًّا فِي عَمَلِ غَيْرِكَ ضَعِيفًا فِي عَمَلِ نَفْسِكَ يَا صَاحِبَ الْعِلْمِ لَا يَشْغَلَنَّكَ الَّذِي لِغَيْرِكَ عَنْ الَّذِي لَكَ يَا صَاحِبَ الْعِلْمِ جَالِسْ الْعُلَمَاءَ وَزَاحِمْهُمْ وَاسْتَمِعْ مِنْهُمْ وَدَعْ مُنَازَعَتَهُمْ يَا صَاحِبَ الْعِلْمِ عَظِّمْ الْعُلَمَاءَ لِعِلْمِهِمْ وَصَغِّرْ الْجُهَّالَ لِجَهْلِهِمْ وَلَا تُبَاعِدْهُمْ وَقَرِّبْهُمْ وَعَلِّمْهُمْ يَا صَاحِبَ الْعِلْمِ لَا تُحَدِّثْ بِحَدِيثٍ فِي مَجْلِسٍ حَتَّى تَفْهَمَهُ وَلَا تُجِبْ امْرَأً فِي قَوْلِهِ حَتَّى تَعْلَمَ مَا قَالَ لَكَ يَا صَاحِبَ الْعِلْمِ لَا تَغْتَرَّ بِاللَّهِ وَلَا تَغْتَرَّ بِالنَّاسِ فَإِنَّ الْغِرَّةَ بِاللَّهِ تَرْكُ أَمْرِهِ وَالْغِرَّةَ بِالنَّاسِ اتِّبَاعُ أَهْوَائِهِمْ وَاحْذَرْ مِنْ اللَّهِ مَا حَذَّرَكَ مِنْ نَفْسِهِ وَاحْذَرْ مِنْ النَّاسِ فِتْنَتَهُمْ يَا صَاحِبَ الْعِلْمِ إِنَّهُ لَا يَكْمُلُ ضَوْءُ النَّهَارِ إِلَّا بِالشَّمْسِ كَذَلِكَ لَا تَكْمُلُ الْحِكْمَةُ إِلَّا بِطَاعَةِ اللَّهِ يَا صَاحِبَ الْعِلْمِ إِنَّهُ لَا يَصْلُحُ الزَّرْعُ إِلَّا بِالْمَاءِ وَالتُّرَابِ كَذَلِكَ لَا يَصْلُحُ الْإِيمَانُ إِلَّا بِالْعِلْمِ وَالْعَمَلِ يَا صَاحِبَ الْعِلْمِ كُلُّ مُسَافِرٍ مُتَزَوِّدٌ وَسَيَجِدُ إِذَا احْتَاجَ إِلَى زَادِهِ مَا تَزَوَّدَ وَكَذَلِكَ سَيَجِدُ كُلُّ عَامِلٍ إِذَا احْتَاجَ إِلَى عَمَلِهِ فِي الْآخِرَةِ مَا عَمِلَ فِي الدُّنْيَا يَا صَاحِبَ الْعِلْمِ إِذَا أَرَادَ اللَّهُ أَنْ يَحُضَّكَ عَلَى عِبَادَتِهِ فَاعْلَمْ أَنَّهُ إِنَّمَا أَرَادَ أَنْ يُبَيِّنَ لَكَ كَرَامَتَكَ عَلَيْهِ فَلَا تَحَوَّلَنَّ إِلَى غَيْرِهِ فَتَرْجِعَ مِنْ كَرَامَتِهِ إِلَى هَوَانِهِ يَا صَاحِبَ الْعِلْمِ إِنَّكَ إِنْ تَنْقُلْ الْحِجَارَةَ وَالْحَدِيدَ أَهْوَنُ عَلَيْكَ مِنْ أَنْ تُحَدِّثَ مَنْ لَا يَعْقِلُ حَدِيثَكَ وَمَثَلُ الَّذِي يُحَدِّثُ مَنْ لَا يَعْقِلُ حَدِيثَهُ كَمَثَلِ الَّذِي يُنَادِي الْمَيِّتَ وَيَضَعُ الْمَائِدَةَ لِأَهْلِ الْقُبُورِ ‏","","",""],[647,647,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ سُلَيْمَانَ أَبُو عَبْدِ الرَّحْمَنِ الْأَنْطَاكِيُّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبَّادٍ الْخَوَّاصِ الشَّامِيِّ أَبِي عُتْبَةَ ‏ ‏قَالَ ‏ ‏أَمَّا بَعْدُ ‏ ‏اعْقِلُوا وَالْعَقْلُ نِعْمَةٌ فَرُبَّ ذِي عَقْلٍ قَدْ شُغِلَ قَلْبُهُ بِالتَّعَمُّقِ عَمَّا هُوَ عَلَيْهِ ضَرَرٌ عَنْ ‏ ‏الِانْتِفَاعِ بِمَا يَحْتَاجُ إِلَيْهِ حَتَّى صَارَ عَنْ ذَلِكَ سَاهِيًا وَمِنْ فَضْلِ عَقْلِ الْمَرْءِ تَرْكُ النَّظَرِ فِيمَا لَا نَظَرَ فِيهِ حَتَّى لَا يَكُونَ فَضْلُ عَقْلِهِ وَبَالًا عَلَيْهِ فِي تَرْكِ مُنَافَسَةِ مَنْ هُوَ دُونَهُ فِي الْأَعْمَالِ الصَّالِحَةِ أَوْ رَجُلٍ شُغِلَ قَلْبُهُ بِبِدْعَةٍ قَلَّدَ فِيهَا دِينَهُ رِجَالًا دُونَ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ اكْتَفَى بِرَأْيِهِ فِيمَا لَا يَرَى الْهُدَى إِلَّا فِيهَا وَلَا يَرَى الضَّلَالَةَ إِلَّا بِتَرْكِهَا يَزْعُمُ أَنَّهُ أَخَذَهَا مِنْ الْقُرْآنِ وَهُوَ يَدْعُو إِلَى فِرَاقِ الْقُرْآنِ أَفَمَا كَانَ لِلْقُرْآنِ حَمَلَةٌ قَبْلَهُ وَقَبْلَ أَصْحَابِهِ يَعْمَلُونَ ‏ ‏بِمُحْكَمِهِ ‏ ‏وَيُؤْمِنُونَ ‏ ‏بِمُتَشَابِهِهِ ‏ ‏وَكَانُوا مِنْهُ عَلَى مَنَارٍ كَوَضَحِ الطَّرِيقِ فَكَانَ الْقُرْآنُ إِمَامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ إِمَامًا لِأَصْحَابِهِ وَكَانَ أَصْحَابُهُ أَئِمَّةً لِمَنْ بَعْدَهُمْ رِجَالٌ مَعْرُوفُونَ مَنْسُوبُونَ فِي الْبُلْدَانِ مُتَّفِقُونَ فِي الرَّدِّ عَلَى أَصْحَابِ الْأَهْوَاءِ مَعَ مَا كَانَ بَيْنَهُمْ مِنْ ‏ ‏الِاخْتِلَافِ ‏ ‏وَتَسَكَّعَ ‏ ‏أَصْحَابُ الْأَهْوَاءِ بِرَأْيِهِمْ فِي سُبُلٍ مُخْتَلِفَةٍ ‏ ‏جَائِرَةٍ ‏ ‏عَنْ الْقَصْدِ مُفَارِقَةٍ لِلصِّرَاطِ الْمُسْتَقِيمِ فَتَوَّهَتْ بِهِمْ ‏ ‏أَدِلَّاؤُهُمْ ‏ ‏فِي ‏ ‏مَهَامِهَ ‏ ‏مُضِلَّةٍ ‏ ‏فَأَمْعَنُوا ‏ ‏فِيهَا ‏ ‏مُتَعَسِّفِينَ ‏ ‏فِي تِيهِهِمْ كُلَّمَا أَحْدَثَ لَهُمْ الشَّيْطَانُ بِدْعَةً فِي ضَلَالَتِهِمْ انْتَقَلُوا مِنْهَا إِلَى غَيْرِهَا لِأَنَّهُمْ لَمْ يَطْلُبُوا أَثَرَ السَّالِفِينَ وَلَمْ يَقْتَدُوا ‏ ‏بِالْمُهَاجِرِينَ ‏ ‏وَقَدْ ذُكِرَ عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِزِيَادٍ ‏ ‏هَلْ تَدْرِي مَا يَهْدِمُ الْإِسْلَامَ ‏ ‏زَلَّةُ ‏ ‏عَالِمٍ وَجِدَالُ مُنَافِقٍ بِالْقُرْآنِ وَأَئِمَّةٌ مُضِلُّونَ اتَّقُوا اللَّهَ وَمَا حَدَثَ فِي قُرَّائِكُمْ وَأَهْلِ مَسَاجِدِكُمْ مِنْ الْغِيبَةِ وَالنَّمِيمَةِ وَالْمَشْيِ بَيْنَ النَّاسِ بِوَجْهَيْنِ وَلِسَانَيْنِ وَقَدْ ذُكِرَ أَنَّ مَنْ كَانَ ذَا وَجْهَيْنِ فِي الدُّنْيَا كَانَ ذَا وَجْهَيْنِ فِي النَّارِ ‏ ‏يَلْقَاكَ صَاحِبُ ‏ ‏الْغِيبَةِ ‏ ‏فَيَغْتَابُ ‏ ‏عِنْدَكَ مَنْ يَرَى أَنَّكَ تُحِبُّ ‏ ‏غِيبَتَهُ ‏ ‏وَيُخَالِفُكَ إِلَى صَاحِبِكَ ‏ ‏فَيَأْتِيهِ عَنْكَ بِمِثْلِهِ فَإِذَا هُوَ قَدْ أَصَابَ عِنْدَ كُلِّ وَاحِدٍ مِنْكُمَا حَاجَتَهُ وَخَفِيَ عَلَى كُلِّ وَاحِدٍ مِنْكُمَا مَا أُتِيَ بِهِ عِنْدَ صَاحِبِهِ حُضُورُهُ عِنْدَ مَنْ حَضَرَهُ حُضُورُ الْإِخْوَانِ ‏ ‏وَغَيْبَتُهُ ‏ ‏عَلَى مَنْ غَابَ عَنْهُ ‏ ‏غَيْبَةُ ‏ ‏الْأَعْدَاءِ مَنْ حَضَرَ مِنْهُمْ كَانَتْ لَهُ ‏ ‏الْأَثَرَةُ ‏ ‏وَمَنْ غَابَ مِنْهُمْ لَمْ تَكُنْ لَهُ حُرْمَةٌ ‏ ‏يَفْتِنُ ‏ ‏مَنْ حَضَرَهُ بِالتَّزْكِيَةِ ‏ ‏وَيَغْتَابُ ‏ ‏مَنْ غَابَ عَنْهُ ‏ ‏بِالْغِيبَةِ ‏ ‏فَيَا لَعِبَادَ اللَّهِ أَمَا فِي الْقَوْمِ مِنْ رَشِيدٍ وَلَا مُصْلِحٍ يَقْمَعُ هَذَا عَنْ مَكِيدَتِهِ وَيَرُدُّهُ عَنْ عِرْضِ أَخِيهِ الْمُسْلِمِ بَلْ عَرَفَ هَوَاهُمْ فِيمَا مَشَى بِهِ إِلَيْهِمْ فَاسْتَمْكَنَ مِنْهُمْ وَأَمْكَنُوهُ مِنْ حَاجَتِهِ فَأَكَلَ بِدِينِهِ مَعَ أَدْيَانِهِمْ فَاللَّهَ اللَّهَ ‏ ‏ذُبُّوا ‏ ‏عَنْ حُرَمِ ‏ ‏أَغْيَابِكُمْ وَكُفُّوا أَلْسِنَتَكُمْ عَنْهُمْ إِلَّا مِنْ خَيْرٍ وَنَاصِحُوا اللَّهَ فِي أُمَّتِكُمْ إِذْ كُنْتُمْ حَمَلَةَ الْكِتَابِ وَالسُّنَّةِ فَإِنَّ الْكِتَابَ لَا يَنْطِقُ حَتَّى يُنْطَقَ بِهِ وَإِنَّ السُّنَّةَ لَا تَعْمَلُ حَتَّى يُعْمَلَ بِهَا فَمَتَى يَتَعَلَّمُ الْجَاهِلُ إِذَا سَكَتَ الْعَالِمُ فَلَمْ يُنْكِرْ مَا ظَهَرَ وَلَمْ يَأْمُرْ بِمَا تُرِكَ وَقَدْ ‏ { ‏أَخَذَ اللَّهُ مِيثَاقَ الَّذِينَ أُوتُوا الْكِتَابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلَا تَكْتُمُونَهُ ‏} ‏اتَّقُوا اللَّهَ فَإِنَّكُمْ فِي زَمَانٍ رَقَّ فِيهِ الْوَرَعُ وَقَلَّ فِيهِ الْخُشُوعُ وَحَمَلَ الْعِلْمَ مُفْسِدُوهُ فَأَحَبُّوا أَنْ يُعْرَفُوا بِحَمْلِهِ وَكَرِهُوا أَنْ يُعْرَفُوا بِإِضَاعَتِهِ فَنَطَقُوا فِيهِ بِالْهَوَى لَمَّا أَدْخَلُوا فِيهِ مِنْ الْخَطَإِ وَحَرَّفُوا الْكَلِمَ عَمَّا تَرَكُوا مِنْ الْحَقِّ إِلَى مَا عَمِلُوا بِهِ مِنْ بَاطِلٍ فَذُنُوبُهُمْ ذُنُوبٌ لَا يُسْتَغْفَرُ مِنْهَا وَتَقْصِيرُهُمْ تَقْصِيرٌ لَا يُعْتَرَفُ بِهِ كَيْفَ ‏ ‏يَهْتَدِي الْمُسْتَدِلُّ الْمُسْتَرْشِدُ إِذَا كَانَ الدَّلِيلُ حَائِرًا أَحَبُّوا الدُّنْيَا وَكَرِهُوا مَنْزِلَةَ أَهْلِهَا فَشَارَكُوهُمْ فِي الْعَيْشِ ‏ ‏وَزَايَلُوهُمْ ‏ ‏بِالْقَوْلِ وَدَافَعُوا بِالْقَوْلِ عَنْ أَنْفُسِهِمْ أَنْ يُنْسَبُوا إِلَى عَمَلِهِمْ فَلَمْ يَتَبَرَّءُوا مِمَّا انْتَفَوْا مِنْهُ وَلَمْ يَدْخُلُوا فِيمَا نَسَبُوا إِلَيْهِ أَنْفُسَهُمْ لِأَنَّ الْعَامِلَ بِالْحَقِّ مُتَكَلِّمٌ وَإِنْ سَكَتَ وَقَدْ ذُكِرَ أَنَّ اللَّهَ تَعَالَى يَقُولُ إِنِّي لَسْتُ كُلَّ كَلَامِ الْحَكِيمِ أَتَقَبَّلُ وَلَكِنِّي أَنْظُرُ إِلَى هَمِّهِ وَهَوَاهُ فَإِنْ كَانَ هَمُّهُ وَهَوَاهُ لِي جَعَلْتُ صَمْتَهُ حَمْدًا وَوَقَارًا لِي وَإِنْ لَمْ يَتَكَلَّمْ وَقَالَ اللَّهُ تَعَالَى ‏ { ‏مَثَلُ الَّذِينَ حُمِّلُوا التَّوْرَاةَ ثُمَّ لَمْ يَحْمِلُوهَا ‏} ‏لَمْ يَعْمَلُوا بِهَا ‏ { ‏كَمَثَلِ الْحِمَارِ يَحْمِلُ أَسْفَارًا ‏} ‏كُتُبًا وَقَالَ ‏ { ‏خُذُوا مَا آتَيْنَاكُمْ بِقُوَّةٍ ‏} ‏قَالَ الْعَمَلُ بِمَا فِيهِ وَلَا تَكْتَفُوا مِنْ السُّنَّةِ ‏ ‏بِانْتِحَالِهَا ‏ ‏بِالْقَوْلِ دُونَ الْعَمَلِ بِهَا فَإِنَّ ‏ ‏انْتِحَالَ ‏ ‏السُّنَّةِ دُونَ الْعَمَلِ بِهَا كَذِبٌ بِالْقَوْلِ مَعَ إِضَاعَةِ الْعَمَلِ وَلَا تَعِيبُوا بِالْبِدَعِ تَزَيُّنًا بِعَيْبِهَا فَإِنَّ فَسَادَ أَهْلِ الْبِدَعِ لَيْسَ بِزَائِدٍ فِي صَلَاحِكُمْ وَلَا تَعِيبُوهَا بَغْيًا عَلَى أَهْلِهَا فَإِنَّ الْبَغْيَ مِنْ فَسَادِ أَنْفُسِكُمْ وَلَيْسَ يَنْبَغِي لِلطَّبِيبِ أَنْ يُدَاوِيَ الْمَرْضَى بِمَا يُبَرِّئُهُمْ وَيُمْرِضُهُ فَإِنَّهُ إِذَا مَرِضَ اشْتَغَلَ بِمَرَضِهِ عَنْ مُدَاوَاتِهِمْ وَلَكِنْ يَنْبَغِي أَنْ يَلْتَمِسَ لِنَفْسِهِ الصِّحَّةَ ‏ ‏لِيَقْوَى بِهِ عَلَى عِلَاجِ الْمَرْضَى فَلْيَكُنْ أَمْرُكُمْ فِيمَا تُنْكِرُونَ عَلَى إِخْوَانِكُمْ نَظَرًا مِنْكُمْ لِأَنْفُسِكُمْ وَنَصِيحَةً مِنْكُمْ لِرَبِّكُمْ وَشَفَقَةً مِنْكُمْ عَلَى إِخْوَانِكُمْ وَأَنْ تَكُونُوا مَعَ ذَلِكَ بِعُيُوبِ أَنْفُسِكُمْ أَعْنَى مِنْكُمْ بِعُيُوبِ غَيْرِكُمْ وَأَنْ ‏ ‏يَسْتَطْعِمَ ‏ ‏بَعْضُكُمْ بَعْضًا النَّصِيحَةَ وَأَنْ ‏ ‏يَحْظَى عِنْدَكُمْ مَنْ بَذَلَهَا لَكُمْ وَقَبِلَهَا مِنْكُمْ وَقَدْ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَحِمَ اللَّهُ مَنْ أَهْدَى إِلَيَّ عُيُوبِي تُحِبُّونَ أَنْ تَقُولُوا فَيُحْتَمَلَ لَكُمْ وَإِنْ قِيلَ لَكُمْ مِثْلُ الَّذِي قُلْتُمْ غَضِبْتُمْ تَجِدُونَ عَلَى النَّاسِ فِيمَا تُنْكِرُونَ مِنْ أُمُورِهِمْ وَتَأْتُونَ مِثْلَ ذَلِكَ فَلَا تُحِبُّونَ أَنْ يُوجَدَ عَلَيْكُمْ اتَّهِمُوا رَأْيَكُمْ وَرَأْيَ أَهْلِ زَمَانِكُمْ وَتَثَبَّتُوا قَبْلَ أَنْ تَكَلَّمُوا وَتَعَلَّمُوا قَبْلَ أَنْ تَعْمَلُوا فَإِنَّهُ يَأْتِي زَمَانٌ يَشْتَبِهُ فِيهِ الْحَقُّ وَالْبَاطِلُ وَيَكُونُ الْمَعْرُوفُ فِيهِ مُنْكَرًا وَالْمُنْكَرُ فِيهِ مَعْرُوفًا فَكَمْ مِنْ مُتَقَرِّبٍ إِلَى اللَّهِ بِمَا يُبَاعِدُهُ وَمُتَحَبِّبٍ إِلَيْهِ بِمَا يُغْضِبُهُ عَلَيْهِ قَالَ اللَّهُ تَعَالَى ‏ { ‏أَفَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ فَرَآهُ حَسَنًا ‏} ‏الْآيَةَ فَعَلَيْكُمْ بِالْوُقُوفِ عِنْدَ الشُّبُهَاتِ حَتَّى يَبْرُزَ لَكُمْ وَاضِحُ الْحَقِّ بِالْبَيِّنَةِ فَإِنَّ الدَّاخِلَ فِيمَا لَا يَعْلَمُ بِغَيْرِ عِلْمٍ آثِمٌ وَمَنْ نَظَرَ لِلَّهِ نَظَرَ اللَّهُ لَهُ عَلَيْكُمْ بِالْقُرْآنِ فَأْتَمُّوا بِهِ وَأُمُّوا بِهِ وَعَلَيْكُمْ بِطَلَبِ أَثَرِ الْمَاضِينَ فِيهِ وَلَوْ أَنَّ ‏ ‏الْأَحْبَارَ ‏ ‏وَالرُّهْبَانَ ‏ ‏لَمْ يَتَّقُوا زَوَالَ مَرَاتِبِهِمْ وَفَسَادَ مَنْزِلَتِهِمْ بِإِقَامَةِ الْكِتَابِ وَتِبْيَانِهِ مَا حَرَّفُوهُ وَلَا كَتَمُوهُ وَلَكِنَّهُمْ لَمَّا خَالَفُوا الْكِتَابَ بِأَعْمَالِهِمْ الْتَمَسُوا أَنْ يَخْدَعُوا قَوْمَهُمْ عَمَّا صَنَعُوا مَخَافَةَ أَنْ تَفْسُدَ مَنَازِلُهُمْ وَأَنْ يَتَبَيَّنَ لِلنَّاسِ فَسَادُهُمْ فَحَرَّفُوا الْكِتَابَ بِالتَّفْسِيرِ وَمَا لَمْ يَسْتَطِيعُوا تَحْرِيفَهُ كَتَمُوهُ فَسَكَتُوا عَنْ صَنِيعِ أَنْفُسِهِمْ إِبْقَاءً عَلَى مَنَازِلِهِمْ وَسَكَتُوا عَمَّا صَنَعَ قَوْمُهُمْ مُصَانَعَةً لَهُمْ وَقَدْ ‏ { ‏أَخَذَ اللَّهُ مِيثَاقَ الَّذِينَ أُوتُوا الْكِتَابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلَا تَكْتُمُونَهُ ‏} ‏بَلْ مَالَئُوا عَلَيْهِ وَرَقَّقُوا لَهُمْ فِيهِ ‏","","",""],[648,648,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا نُهِينَا أَنْ ‏ ‏نَبْتَدِئَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعْجِبُنَا أَنْ يَقْدُمَ ‏ ‏الْبَدَوِيُّ وَالْأَعْرَابِيُّ الْعَاقِلُ فَيَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ عِنْدَهُ فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ جَاءَ أَعْرَابِيٌّ ‏ ‏فَجَثَا ‏ ‏بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ رَسُولَكَ أَتَانَا فَزَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ اللَّهَ أَرْسَلَكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ فَبِالَّذِي رَفَعَ السَّمَاءَ وَبَسَطَ الْأَرْضَ وَنَصَبَ الْجِبَالَ ‏ ‏آللَّهُ أَرْسَلَكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ قَالَ فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ قَالَ فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ عَلَيْنَا صَوْمَ شَهْرٍ فِي السَّنَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا قَالَ نَعَمْ قَالَ فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ عَلَيْنَا فِي أَمْوَالِنَا الزَّكَاةَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ قَالَ فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ عَلَيْنَا الْحَجَّ إِلَى الْبَيْتِ مَنْ اسْتَطَاعَ إِلَيْهِ سَبِيلًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ قَالَ فَوَالَّذِي بَعَثَكَ بِالْحَقِّ لَا أَدَعُ مِنْهُنَّ شَيْئًا وَلَا ‏ ‏أُجَاوِزُهُنَّ ‏ ‏قَالَ ثُمَّ ‏ ‏وَثَبَ ‏ ‏الْأَعْرَابِيُّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ صَدَقَ الْأَعْرَابِيُّ دَخَلَ الْجَنَّةَ ‏","","",""],[649,649,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ السَّلَامُ عَلَيْكَ يَا غُلَامَ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ وَعَلَيْكَ وَقَالَ إِنِّي رَجُلٌ مِنْ أَخْوَالِكَ مِنْ ‏ ‏بَنِي سَعْدِ بْنِ بَكْرٍ ‏ ‏وَأَنَا رَسُولُ قَوْمِي إِلَيْكَ وَوَافِدُهُمْ وَإِنِّي سَائِلُكَ فَمُشَدِّدٌ مَسْأَلَتِي إِلَيْكَ ‏ ‏وَمُنَاشِدُكَ ‏ ‏فَمُشَدِّدٌ ‏ ‏مُنَاشَدَتِي ‏ ‏إِيَّاكَ قَالَ خُذْ عَنْكَ يَا أَخَا ‏ ‏بَنِي سَعْدٍ ‏ ‏قَالَ مَنْ خَلَقَكَ وَخَلَقَ مَنْ قَبْلَكَ وَمَنْ هُوَ خَالِقُ مَنْ بَعْدَكَ قَالَ اللَّهُ قَالَ ‏ ‏فَنَشَدْتُكَ ‏ ‏بِذَلِكَ أَهُوَ أَرْسَلَكَ قَالَ نَعَمْ قَالَ مَنْ خَلَقَ السَّمَوَاتِ السَّبْعَ وَالْأَرَضِينَ السَّبْعَ وَأَجْرَى بَيْنَهُنَّ الرِّزْقَ قَالَ اللَّهُ قَالَ ‏ ‏فَنَشَدْتُكَ ‏ ‏بِذَلِكَ أَهُوَ أَرْسَلَكَ قَالَ نَعَمْ قَالَ إِنَّا وَجَدْنَا فِي كِتَابِكَ وَأَمَرَتْنَا رُسُلُكَ أَنْ نُصَلِّيَ فِي الْيَوْمِ وَاللَّيْلَةِ خَمْسَ صَلَوَاتٍ لِمَوَاقِيتِهَا ‏ ‏فَنَشَدْتُكَ ‏ ‏بِذَلِكَ أَهُوَ أَمَرَكَ قَالَ نَعَمْ قَالَ فَإِنَّا وَجَدْنَا فِي كِتَابِكَ وَأَمَرَتْنَا رُسُلُكَ أَنْ نَأْخُذَ مِنْ ‏ ‏حَوَاشِي ‏ ‏أَمْوَالِنَا فَنَرُدَّهَا عَلَى فُقَرَائِنَا ‏ ‏فَنَشَدْتُكَ ‏ ‏بِذَلِكَ أَهُوَ أَمَرَكَ بِذَلِكَ قَالَ نَعَمْ ثُمَّ قَالَ أَمَّا الْخَامِسَةُ فَلَسْتُ بِسَائِلِكَ عَنْهَا وَلَا ‏ ‏أَرَبَ ‏ ‏لِي فِيهَا ثُمَّ قَالَ أَمَا وَالَّذِي بَعَثَكَ بِالْحَقِّ لَأَعْمَلَنَّ بِهَا وَمَنْ أَطَاعَنِي مِنْ قَوْمِي ثُمَّ رَجَعَ فَضَحِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ ‏","","",""],[650,650,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏وَمُحَمَّدُ بْنُ الْوَلِيدِ بْنِ نُوَيْفِعٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بَعَثَ ‏ ‏بَنُو سَعْدِ بْنِ بَكْرٍ ‏ ‏ضِمَامَ بْنَ ثَعْلَبَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَدِمَ عَلَيْهِ ‏ ‏فَأَنَاخَ ‏ ‏بَعِيرَهُ عَلَى بَابِ الْمَسْجِدِ ثُمَّ ‏ ‏عَقَلَهُ ‏ ‏ثُمَّ دَخَلَ الْمَسْجِدَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فِي أَصْحَابِهِ وَكَانَ ‏ ‏ضِمَامٌ ‏ ‏رَجُلًا ‏ ‏جَلْدًا ‏ ‏أَشْعَرَ ‏ ‏ذَا ‏ ‏غَدِيرَتَيْنِ ‏ ‏حَتَّى وَقَفَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُّكُمْ ‏ ‏ابْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏ابْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ نَعَمْ قَالَ يَا ‏ ‏ابْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏إِنِّي سَائِلُكَ وَمُغَلِّظٌ فِي الْمَسْأَلَةِ فَلَا تَجِدَنَّ فِي نَفْسِكَ قَالَ لَا أَجِدُ فِي نَفْسِي فَسَلْ عَمَّا بَدَا لَكَ قَالَ إِنِّي ‏ ‏أَنْشُدُكَ ‏ ‏بِاللَّهِ إِلَهِكَ وَإِلَهِ مَنْ كَانَ قَبْلَكَ وَإِلَهِ مَنْ هُوَ كَائِنٌ بَعْدَكَ ‏ ‏آللَّهُ بَعَثَكَ إِلَيْنَا رَسُولًا قَالَ اللَّهُمَّ نَعَمْ قَالَ ‏ ‏فَأَنْشُدُكَ ‏ ‏بِاللَّهِ إِلَهِكَ وَإِلَهِ مَنْ كَانَ قَبْلَكَ وَإِلَهِ مَنْ هُوَ كَائِنٌ بَعْدَكَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ نَعْبُدَهُ وَحْدَهُ لَا نُشْرِكُ بِهِ شَيْئًا وَأَنْ ‏ ‏نَخْلَعَ ‏ ‏هَذِهِ ‏ ‏الْأَنْدَادَ ‏ ‏الَّتِي كَانَتْ آبَاؤُنَا تَعْبُدُهَا مِنْ دُونِهِ قَالَ اللَّهُمَّ نَعَمْ قَالَ ‏ ‏فَأَنْشُدُكَ ‏ ‏بِاللَّهِ إِلَهِكَ وَإِلَهِ مَنْ كَانَ قَبْلَكَ وَإِلَهِ مَنْ هُوَ كَائِنٌ بَعْدَكَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ نُصَلِّيَ هَذِهِ الصَّلَوَاتِ الْخَمْسَ قَالَ اللَّهُمَّ نَعَمْ قَالَ ثُمَّ جَعَلَ يَذْكُرُ فَرَائِضَ الْإِسْلَامِ فَرِيضَةً فَرِيضَةً الزَّكَاةَ وَالصِّيَامَ وَالْحَجَّ وَشَرَائِعَ الْإِسْلَامِ كُلَّهَا ‏ ‏وَيُنَاشِدُهُ ‏ ‏عِنْدَ كُلِّ فَرِيضَةٍ كَمَا ‏ ‏نَاشَدَهُ ‏ ‏فِي الَّتِي قَبْلَهَا حَتَّى إِذَا فَرَغَ قَالَ فَإِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏ ‏وَسَأُؤَدِّي هَذِهِ الْفَرِيضَةَ وَأَجْتَنِبُ مَا نَهَيْتَنِي عَنْهُ ثُمَّ قَالَ لَا أَزِيدُ وَلَا أُنْقِصُ ثُمَّ انْصَرَفَ إِلَى بَعِيرِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وَلَّى ‏ ‏إِنْ يَصْدُقْ ذُو ‏ ‏الْعَقِيصَتَيْنِ ‏ ‏يَدْخُلْ الْجَنَّةَ فَأَتَى إِلَى بَعِيرِهِ فَأَطْلَقَ ‏ ‏عِقَالَهُ ‏ ‏ثُمَّ خَرَجَ حَتَّى قَدِمَ عَلَى قَوْمِهِ فَاجْتَمَعُوا إِلَيْهِ فَكَانَ أَوَّلَ مَا تَكَلَّمَ أَنْ قَالَ بِاسْتِ اللَّاتِ وَالْعُزَّى قَالُوا ‏ ‏مَهْ ‏ ‏يَا ‏ ‏ضِمَامُ ‏ ‏اتَّقِ الْبَرَصَ وَاتَّقِ الْجُنُونَ وَاتَّقِ ‏ ‏الْجُذَامَ ‏ ‏قَالَ وَيْلَكُمْ إِنَّهُمَا وَاللَّهِ مَا يَضُرَّانِ وَلَا يَنْفَعَانِ إِنَّ اللَّهَ قَدْ بَعَثَ رَسُولًا وَأَنْزَلَ عَلَيْهِ كِتَابًا اسْتَنْقَذَكُمْ بِهِ مِمَّا كُنْتُمْ فِيهِ وَإِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ وَقَدْ جِئْتُكُمْ مِنْ عِنْدِهِ بِمَا أَمَرَكُمْ بِهِ وَنَهَاكُمْ عَنْهُ قَالَ فَوَاللَّهِ مَا أَمْسَى مِنْ ذَلِكَ الْيَوْمِ وَفِي حَاضِرِهِ رَجُلٌ وَلَا امْرَأَةٌ إِلَّا مُسْلِمًا قَالَ يَقُولُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَمَا سَمِعْنَا بِوَافِدِ قَوْمٍ كَانَ أَفْضَلَ مِنْ ‏ ‏ضِمَامِ بْنِ ثَعْلَبَةَ ‏","","",""],[651,651,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ هُوَ ابْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْعَرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الطُّهُورُ شَطْرُ الْإِيمَانِ وَالْحَمْدُ لِلَّهِ يَمْلَأُ الْمِيزَانَ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ يَمْلَآَنِ مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ وَالصَّلَاةُ نُورٌ وَالصَّدَقَةُ بُرْهَانٌ وَالْوُضُوءُ ضِيَاءٌ وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ وَكُلُّ النَّاسِ ‏ ‏يَغْدُو ‏ ‏فَبَائِعٌ نَفْسَهُ ‏ ‏فَمُعْتِقُهَا ‏ ‏أَوْ ‏ ‏مُوبِقُهَا ‏","","",""],[652,652,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏جُرَيٍّ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏قَالَ ‏ ‏عَقَدَهُنَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَدِي ‏ ‏أَوْ قَالَ ‏ ‏عَقَدَهُنَّ ‏ ‏فِي يَدِهِ ‏ ‏وَيَدُهُ فِي يَدِي ‏ ‏سُبْحَانَ اللَّهِ نِصْفُ الْإِيمَانِ وَالْحَمْدُ لِلَّهِ يَمْلَأُ الْمِيزَانَ وَاللَّهُ أَكْبَرُ يَمْلَأُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ وَالْوُضُوءُ نِصْفُ الْإِيمَانِ وَالصَّوْمُ نِصْفُ الصَّبْرِ ‏","","",""],[653,653,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا وَلَنْ تُحْصُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَقَالَ الْآخَرُ إِنَّ مِنْ خَيْرِ أَعْمَالِكُمْ الصَّلَاةَ وَلَنْ يُحَافِظَ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""],[654,654,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَا كَبْشَةَ السَّلُولِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏ثَوْبَانَ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَخَيْرُ أَعْمَالِكُمْ الصَّلَاةُ وَلَنْ يُحَافِظَ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""],[655,655,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَسْعُودُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏كَانَ ‏ ‏يُصَلِّي الصَّلَوَاتِ كُلَّهَا بِوُضُوءٍ وَاحِدٍ ‏ ‏وَأَنَّ ‏ ‏عَلِيًّا ‏ ‏كَانَ يَتَوَضَّأُ لِكُلِّ صَلَاةٍ وَتَلَا هَذِهِ الْآيَةَ ‏ { ‏إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ ‏} ‏الْآيَةَ ‏","","",""],[656,656,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قُلْتُ أَرَأَيْتَ تَوَضُّؤَ ‏ ‏ابْنِ عُمَرَ ‏ ‏لِكُلِّ صَلَاةٍ طَاهِرًا أَوْ غَيْرَ طَاهِرٍ عَمَّ ذَلِكَ قَالَ حَدَّثَتْهُ ‏ ‏أَسْمَاءُ بِنْتُ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ حَنْظَلَةَ بْنِ أَبِي عَامِرٍ ‏ ‏حَدَّثَهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرَ بِالْوُضُوءِ لِكُلِّ صَلَاةٍ طَاهِرًا أَوْ غَيْرَ طَاهِرٍ فَلَمَّا شَقَّ ذَلِكَ عَلَيْهِ أُمِرَ بِالسِّوَاكِ لِكُلِّ صَلَاةٍ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَرَى أَنَّ بِهِ عَلَى ذَلِكَ قُوَّةً فَكَانَ لَا يَدَعُ الْوُضُوءَ لِكُلِّ صَلَاةٍ ‏","","",""],[657,657,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ حَتَّى كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏صَلَّى الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ وَمَسَحَ عَلَى خُفَّيْهِ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَأَيْتُكَ صَنَعْتَ شَيْئًا لَمْ تَكُنْ تَصْنَعُهُ قَالَ إِنِّي عَمْدًا صَنَعْتُ يَا ‏ ‏عُمَرُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏فَدَلَّ فِعْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ مَعْنَى قَوْلِ اللَّهِ تَعَالَى ‏ { ‏إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ ‏} ‏الْآيَةَ لِكُلِّ مُحْدِثٍ لَيْسَ لِلطَّاهِرِ وَمِنْهُ قَوْلُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وُضُوءَ إِلَّا مِنْ حَدَثٍ وَاللَّهُ أَعْلَمُ ‏","","",""],[658,658,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَهَبَ إِلَى الْحَاجَةِ أَبْعَدَ ‏","","",""],[659,659,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَبَرَّزَ تَبَاعَدَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هُوَ الْأَدَبُ ‏","","",""],[660,660,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ الْحِمْيَرِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو سَعِيدٍ الْخَيْرُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اكْتَحَلَ ‏ ‏فَلْيُوتِرْ ‏ ‏مَنْ فَعَلَ ذَلِكَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ مَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏ ‏مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ مَنْ أَكَلَ ‏ ‏فَلْيَتَخَلَّلْ ‏ ‏فَمَا ‏ ‏تَخَلَّلَ ‏ ‏فَلْيَلْفِظْ ‏ ‏وَمَا لَاكَ بِلِسَانِهِ فَلْيَبْتَلِعْ مَنْ أَتَى ‏ ‏الْغَائِطَ ‏ ‏فَلْيَسْتَتِرْ فَإِنْ لَمْ يَجِدْ إِلَّا ‏ ‏كَثِيبَ ‏ ‏رَمْلٍ ‏ ‏فَلْيَسْتَدْبِرْهُ ‏ ‏فَإِنَّ الشَّيَاطِينَ يَتَلَاعَبُونَ بِمَقَاعِدِ بَنِي ‏ ‏آدَمَ ‏ ‏مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ ‏","","",""],[661,661,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ مَا اسْتَتَرَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ‏ ‏هَدَفٌ ‏ ‏أَوْ ‏ ‏حَائِشُ ‏ ‏نَخْلٍ ‏","","",""],[662,662,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ مَالِكٍ ‏ ‏مِنْ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏مَوْلَى ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ أَنْتَ رَسُولِي إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَقُلْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ عَلَيْكُمْ السَّلَامَ وَيَأْمُرُكُمْ ‏ ‏إِذَا خَرَجْتُمْ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا ‏ ‏تَسْتَدْبِرُوهَا ‏","","",""],[663,663,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَيْتُمْ الْغَائِطَ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ بِغَائِطٍ وَلَا بَوْلٍ وَلَا ‏ ‏تَسْتَدْبِرُوهَا ‏ ‏قَالَ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَدِمْنَا ‏ ‏الشَّامَ ‏ ‏فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ عِنْدَ الْقِبْلَةِ ‏ ‏فَنَنْحَرِفُ ‏ ‏وَنَسْتَغْفِرُ اللَّهَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏وَهَذَا أَصَحُّ مِنْ حَدِيثِ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏وَعَبْدُ الْكَرِيمِ ‏ ‏شِبْهُ الْمَتْرُوكِ ‏","","",""],[664,664,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ السَّلَامِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَرْفَعُ ثَوْبَهُ حَتَّى يَدْنُوَ مِنْ الْأَرْضِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هُوَ أَدَبٌ وَهُوَ أَشْبَهُ مِنْ حَدِيثِ ‏ ‏الْمُغِيرَةِ ‏","","",""],[665,665,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ يَحْيَى بْنِ حَبَّانَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَمَّهُ ‏ ‏وَاسِعَ بْنَ حَبَّانَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ظَهْرِ بَيْتِنَا فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا عَلَى ‏ ‏لَبِنَتَيْنِ ‏ ‏مُسْتَقْبِلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏","","",""],[666,666,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏سُبَاطَةِ ‏ ‏قَوْمٍ ‏ ‏فَبَالَ وَهُوَ قَائِمٌ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏لَا أَعْلَمُ فِيهِ كَرَاهِيَةً ‏","","",""],[667,667,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[668,668,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قُرْطٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى ‏ ‏الْغَائِطِ ‏ ‏فَلْيَذْهَبْ مَعَهُ بِثَلَاثَةِ أَحْجَارٍ ‏ ‏يَسْتَطِيبُ ‏ ‏بِهِنَّ فَإِنَّهَا تُجْزِئُ عَنْهُ ‏","","",""],[669,669,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيٌّ هُوَ ابْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خُزَيْمَةَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ خُزَيْمَةَ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةُ أَحْجَارٍ لَيْسَ مِنْهُنَّ ‏ ‏رَجِيعٌ ‏ ‏يَعْنِي ‏ ‏الِاسْتِطَابَةَ ‏","","",""],[670,670,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ هُوَ ابْنُ أَبِي الْمُخَارِقِ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ مَالِكٍ ‏ ‏مِنْ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏مَوْلَى ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ أَنْتَ رَسُولِي إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَقُلْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ عَلَيْكُمْ السَّلَامَ وَيَأْمُرُكُمْ أَنْ ‏ ‏لَا ‏ ‏تَسْتَنْجُوا ‏ ‏بِعَظْمٍ وَلَا بِبَعْرَةٍ ‏ ‏قَالَ ‏ ‏أَبُو عَاصِمٍ ‏ ‏مَرَّةً وَيَنْهَاكُمْ ‏ ‏أَوْ يَأْمُرُكُمْ ‏","","",""],[671,671,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمَسَّ أَحَدُكُمْ ذَكَرَهُ بِيَمِينِهِ وَلَا ‏ ‏يَتَمَسَّحْ ‏ ‏بِيَمِينِهِ ‏","","",""],[672,672,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَنَا لَكُمْ مِثْلُ الْوَالِدِ لِلْوَلَدِ أُعَلِّمُكُمْ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا ‏ ‏تَسْتَدْبِرُوهَا ‏ ‏وَإِذَا ‏ ‏اسْتَطَبْتَ ‏ ‏فَلَا ‏ ‏تَسْتَطِبْ ‏ ‏بِيَمِينِكَ وَكَانَ يَأْمُرُنَا بِثَلَاثَةِ أَحْجَارٍ ‏ ‏وَيَنْهَى عَنْ ‏ ‏الرَّوْثِ ‏ ‏وَالرِّمَّةِ ‏ ‏قَالَ ‏ ‏زَكَرِيَّا ‏ ‏يَعْنِي الْعِظَامَ الْبَالِيَةَ ‏","","",""],[673,673,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ذَهَبَ لِحَاجَتِهِ أَتَيْتُهُ أَنَا وَغُلَامٌ ‏ ‏بِعَنَزَةٍ ‏ ‏وَإِدَاوَةٍ ‏ ‏فَيَتَوَضَّأُ ‏","","",""],[674,674,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ الْخَلَاءِ جَاءَ الْغُلَامُ ‏ ‏بِإِدَاوَةٍ ‏ ‏مِنْ مَاءٍ كَانَ ‏ ‏يَسْتَنْجِي ‏ ‏بِهِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَبُو مُعَاذٍ ‏ ‏اسْمُهُ ‏ ‏عَطَاءُ بْنُ مَنِيعٍ أَبِي مَيْمُونَةٍ ‏","","",""],[675,675,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏الْمُسَيَّبِ بْنِ نَجَبَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَمَّتِي ‏ ‏وَكَانَتْ تَحْتَ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ ‏ ‏حُذَيْفَةَ ‏ ‏كَانَ يَسْتَنْجِي بِالْمَاءِ ‏","","",""],[676,676,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْتِنِي بِوَضُوءٍ ثُمَّ دَخَلَ ‏ ‏غَيْضَةً ‏ ‏فَأَتَيْتُهُ بِمَاءٍ ‏ ‏فَاسْتَنْجَى ‏ ‏ثُمَّ مَسَحَ يَدَهُ بِالتُّرَابِ ثُمَّ غَسَلَ يَدَيْهِ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[677,677,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ الْخَلَاءِ قَالَ غُفْرَانَكَ ‏","","",""],[678,678,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ الْحَبْحَابِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ ‏","","",""],[679,679,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ الْحَبْحَابِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ ‏","","",""],[680,680,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِهِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي السِّوَاكَ ‏","","",""],[681,681,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ هُوَ الْقَطْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْمَعِيلَ بْنِ أَبِي حَبِيبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏دَاوُدُ بْنُ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ ‏","","",""],[682,682,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى ‏ ‏التَّهَجُّدِ ‏ ‏يَشُوصُ ‏ ‏فَاهُ بِالسِّوَاكِ ‏","","",""],[683,683,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقْبَلُ اللَّهُ صَلَاةً بِغَيْرِ طُهُورٍ وَلَا صَدَقَةً مِنْ ‏ ‏غُلُولٍ ‏","","",""],[684,684,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِفْتَاحُ الصَّلَاةِ الطُّهُورُ وَتَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ ‏","","",""],[685,685,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَيْحَانَةَ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏","","",""],[686,686,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمَكُّوكِ ‏ ‏وَيَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِي ‏","","",""],[687,687,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينَا فِي مَنْزِلِنَا ‏ ‏فَآخُذُ ‏ ‏مِيضَأَةً ‏ ‏لَنَا تَكُونُ ‏ ‏مُدًّا ‏ ‏وَثُلُثَ ‏ ‏مُدٍّ ‏ ‏أَوْ رُبُعَ مُدٍّ ‏ ‏فَأَسْكُبُ عَلَيْهِ فَيَتَوَضَّأُ ثَلَاثًا ثَلَاثًا ‏","","",""],[688,688,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْعَقَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏رُبَيْحُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عَلَيْهِ ‏","","",""],[689,689,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَمْرِو بْنِ أَوْسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏فَاسْتَوْكَفَ ‏ ‏ثَلَاثًا فَقُلْتُ أَنَا لَهُ أَيُّ شَيْءٍ ‏ ‏اسْتَوْكَفَ ‏ ‏ثَلَاثًا قَالَ غَسَلَ يَدَيْهِ ثَلَاثًا ‏","","",""],[690,690,"","","‏ ‏أَخْبَرَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏تَوَضَّأَ فَمَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ كَمَا تَوَضَّأْتُ ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[691,691,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏وَخَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدٍ ‏ ‏دَعَا ‏ ‏بِتَوْرٍ ‏ ‏مِنْ مَاءٍ ‏ ‏فَأَكْفَأَ ‏ ‏عَلَى يَدَيْهِ فَغَسَلَهُمَا ثَلَاثَ مَرَّاتٍ وَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ مَرَّتَيْنِ مَرَّتَيْنِ ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوًا مِنْهُ ‏","","",""],[692,692,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَلَا أُنَبِّئُكُمْ ‏ ‏أَوْ أَلَا أُخْبِرُكُمْ ‏ ‏بِوُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ مَرَّةً مَرَّةً ‏ ‏أَوْ قَالَ مَرَّةً مَرَّةً ‏","","",""],[693,693,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ الدَّرَاوَرْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً جَمَعَ بَيْنَ الْمَضْمَضَةِ ‏ ‏وَالِاسْتِنْشَاقِ ‏","","",""],[694,694,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللَّهُ بِهِ الْخَطَايَا وَيَزِيدُ بِهِ فِي الْحَسَنَاتِ قَالُوا بَلَى قَالَ ‏ ‏إِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى الْمَكْرُوهَاتِ وَكَثْرَةُ ‏ ‏الْخُطَا إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ مَسْعُودٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ هُوَ ابْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ‏ ‏بِنَحْوِهِ ‏","","",""],[695,695,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَهْضَمِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْنَا ‏ ‏بِإِسْبَاغِ ‏ ‏الْوُضُوءِ ‏","","",""],[696,696,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَلْقَمَةَ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ خَيْرٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَلِيٌّ ‏ ‏الرَّحَبَةَ ‏ ‏بَعْدَمَا صَلَّى الْفَجْرَ قَالَ فَجَلَسَ فِي ‏ ‏الرَّحَبَةِ ‏ ‏ثُمَّ ‏ ‏قَالَ لِغُلَامٍ لَهُ ‏ ‏ائْتِنِي بِطَهُورٍ قَالَ فَأَتَاهُ الْغُلَامُ بِإِنَاءٍ فِيهِ مَاءٌ ‏ ‏وَطَسْتٍ ‏ ‏قَالَ ‏ ‏عَبْدُ خَيْرٍ ‏ ‏وَنَحْنُ جُلُوسٌ نَنْظُرُ إِلَيْهِ ‏ ‏فَأَدْخَلَ يَدَهُ الْيُمْنَى فَمَلَأَ فَمَهُ فَمَضْمَضَ وَاسْتَنْشَقَ ‏ ‏وَنَثَرَ ‏ ‏بِيَدِهِ الْيُسْرَى فَعَلَ هَذَا ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى طُهُورِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَذَا طُهُورُهُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ عُقْبَةَ الْمُرَادِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ خَيْرٍ ‏ ‏بِإِسْنَادِهِ ‏ ‏نَحْوَهُ ‏","","",""],[697,697,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَائِذِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتَنْشَقَ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[698,698,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏تَوَضَّأَ ‏ ‏فَخَلَّلَ ‏ ‏لِحْيَتَهُ وَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏","","",""],[699,699,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْمَعِيلُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَافِدِ ‏ ‏بَنِي الْمُنْتَفِقِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَأَسْبِغْ ‏ ‏وُضُوءَكَ ‏ ‏وَخَلِّلْ ‏ ‏بَيْنَ أَصَابِعِكَ ‏","","",""],[700,700,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرٌ هُوَ ابْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏","","",""],[701,701,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ يَمُرُّ بِنَا وَالنَّاسُ يَتَوَضَّئُونَ مِنْ ‏ ‏الْمِطْهَرَةِ ‏ ‏وَيَقُولُ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا أَعْجَبُ إِلَيَّ مِنْ حَدِيثِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏","","",""],[702,702,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏تَوَضَّأَ فَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ كَمَا صَنَعْتُ ‏ ‏أَوْ كَالَّذِي صَنَعْتُ ‏","","",""],[703,703,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ بْنُ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْجُحْفَةِ ‏ ‏فَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ ثَلَاثًا ثُمَّ مَسَحَ رَأْسَهُ وَغَسَلَ رِجْلَيْهِ حَتَّى أَنْقَاهُمَا ثُمَّ مَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ فَضْلِ يَدَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يُرِيدُ بِهِ تَفْسِيرَ مَسْحِ الْأَوَّلِ ‏","","",""],[704,704,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ وَالْعِمَامَةِ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَأْخُذُ بِهِ ‏ ‏قَالَ ‏ ‏إِي وَاللَّهِ ‏","","",""],[705,705,"","","‏ ‏أَخْبَرَنَا ‏ ‏قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً ‏ ‏وَنَضَحَ ‏ ‏فَرْجَهُ ‏","","",""],[706,706,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏مَيْمُونَةَ ‏ ‏خَالَتِي عَنْ غُسْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ ‏ ‏فَقَالَتْ كَانَ ‏ ‏يُؤْتَى بِالْإِنَاءِ فَيُفْرِغُ بِيَمِينِهِ عَلَى شِمَالِهِ فَيَغْسِلُ فَرْجَهُ وَمَا أَصَابَهُ ثُمَّ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يَغْسِلُ رَأْسَهُ وَسَائِرَ جَسَدِهِ ثُمَّ يَتَحَوَّلُ فَيَغْسِلُ رِجْلَيْهِ ثُمَّ يُؤْتَى بِالْمِنْدِيلِ فَيَضَعُهُ بَيْنَ يَدَيْهِ فَيَنْفُضُ أَصَابِعَهُ وَلَا يَمَسُّهُ ‏","","",""],[707,707,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا هُوَ ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فِي سَفَرٍ فَقَالَ ‏ ‏أَمَعَكَ مَاءٌ فَقُلْتُ نَعَمْ فَنَزَلَ عَنْ رَاحِلَتِهِ فَمَشَى حَتَّى تَوَارَى عَنِّي فِي سَوَادِ اللَّيْلِ ثُمَّ جَاءَ فَأَفْرَغْتُ عَلَيْهِ مِنْ ‏ ‏الْإِدَاوَةِ ‏ ‏فَغَسَلَ يَدَيْهِ وَوَجْهَهُ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏مِنْ صُوفٍ فَلَمْ يَسْتَطِعْ أَنْ يُخْرِجَ ذِرَاعَيْهِ مِنْهَا حَتَّى أَخْرَجَهُمَا مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ ثُمَّ أَهْوَيْتُ لِأَنْزِعَ خُفَّيْهِ فَقَالَ دَعْهُمَا فَإِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ فَمَسَحَ عَلَيْهِمَا ‏","","",""],[708,708,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةَ أَيَّامٍ ‏ ‏وَلَيَالِيَهُنَّ لِلْمُسَافِرِ وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ ‏ ‏يَعْنِي الْمَسْحَ عَلَى الْخُفَّيْنِ ‏","","",""],[709,709,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى النَّعْلَيْنِ فَوَسَّعَ ثُمَّ قَالَ لَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ كَمَا رَأَيْتُمُونِي فَعَلْتُ لَرَأَيْتُ أَنَّ بَاطِنَ الْقَدَمَيْنِ أَحَقُّ بِالْمَسْحِ مِنْ ظَاهِرِهِمَا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا الْحَدِيثُ مَنْسُوخٌ بِقَوْلِهِ تَعَالَى ‏ { ‏وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ ‏}","","",""],[710,710,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَقِيلٍ زُهْرَةُ بْنُ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَمِّهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَجَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا يُحَدِّثُ أَصْحَابَهُ فَقَالَ ‏ ‏مَنْ قَامَ إِذَا ‏ ‏اسْتَقَلَّتْ ‏ ‏الشَّمْسُ فَتَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ صَلَّى رَكْعَتَيْنِ خَرَجَ مِنْ ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ فَقَالَ ‏ ‏عُقْبَةُ ‏ ‏فَقُلْتُ الْحَمْدُ لِلَّهِ الَّذِي رَزَقَنِي أَنْ أَسْمَعَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَكَانَ تُجَاهِي جَالِسًا ‏ ‏أَتَعْجَبُ مِنْ هَذَا فَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْجَبَ مِنْ هَذَا قَبْلَ أَنْ تَأْتِيَ فَقُلْتُ وَمَا ذَلِكَ بِأَبِي أَنْتَ وَأُمِّي ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ رَفَعَ بَصَرَهُ إِلَى السَّمَاءِ ‏ ‏أَوْ قَالَ نَظَرَهُ إِلَى السَّمَاءِ ‏ ‏فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فُتِحَتْ لَهُ ثَمَانِيَةُ أَبْوَابِ الْجَنَّةِ يَدْخُلُ مِنْ أَيِّهِنَّ شَاءَ ‏","","",""],[711,711,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ سُفْيَانَ ‏ ‏أَنَّهُمْ غَزَوْا غَزْوَةَ السَّلَاسِلِ فَرَجَعُوا إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏وَعِنْدَهُ ‏ ‏أَبُو أَيُّوبَ ‏ ‏وَعُقْبَةُ بْنُ عَامِرٍ ‏ ‏فَقَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ كَمَا أُمِرَ وَصَلَّى كَمَا أُمِرَ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ عَمَلٍ أَكَذَاكَ يَا ‏ ‏عُقْبَةُ ‏ ‏قَالَ نَعَمْ ‏","","",""],[712,712,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ ‏ ‏أَوْ الْمُؤْمِنُ ‏ ‏فَغَسَلَ وَجْهَهُ خَرَجَتْ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنِهِ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ ‏ ‏بَطَشَتْهَا ‏ ‏يَدَاهُ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏حَتَّى يَخْرُجَ نَقِيًّا مِنْ الذُّنُوبِ ‏","","",""],[713,713,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏سَلْمَانَ ‏ ‏تَحْتَ شَجَرَةٍ فَأَخَذَ مِنْهَا غُصْنًا يَابِسًا فَهَزَّهُ حَتَّى ‏ ‏تَحَاتَّ ‏ ‏وَرَقُهُ قَالَ أَمَا تَسْأَلُنِي لِمَ أَفْعَلُ هَذَا قُلْتُ لَهُ لِمَ فَعَلْتَهُ قَالَ هَكَذَا فَعَلَ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ وَصَلَّى الْخَمْسَ ‏ ‏تَحَاتَّتْ ‏ ‏ذُنُوبُهُ كَمَا ‏ ‏تَحَاتَّ ‏ ‏هَذَا الْوَرَقُ ثُمَّ قَالَ ‏ { ‏وَأَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ وَزُلَفًا مِنْ اللَّيْلِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ ‏}","","",""],[714,714,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ وَكَانَ أَحَدُنَا يَكْفِيهِ الْوُضُوءُ مَا لَمْ يُحْدِثْ ‏","","",""],[715,715,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَجَدَ أَحَدُكُمْ فِي صَلَاتِهِ حَرَكَةً فِي دُبُرِهِ فَأَشْكَلَ عَلَيْهِ أَحْدَثَ أَوْ لَمْ يُحْدِثْ فَلَا يَنْصَرِفَنَّ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[716,716,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مَرْيَمَ ‏ ‏حَدَّثَنِي ‏ ‏عَطِيَّةُ بْنُ قَيْسٍ الْكَلَاعِيُّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الْعَيْنَانِ وِكَاءُ ‏ ‏السَّهِ ‏ ‏فَإِذَا نَامَتْ الْعَيْنُ اسْتَطْلَقَ ‏ ‏الْوِكَاءُ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ عَبْدِ اللَّهِ ‏ ‏تَقُولُ بِهِ ‏ ‏قَالَ ‏ ‏لَا إِذَا نَامَ قَائِمًا لَيْسَ عَلَيْهِ الْوُضُوءُ ‏","","",""],[717,717,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَلْقَى مِنْ ‏ ‏الْمَذْيِ ‏ ‏شِدَّةً فَكُنْتُ أُكْثِرُ الْغُسْلَ مِنْهُ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَأَلْتُهُ عَنْهُ فَقَالَ ‏ ‏إِنَّمَا يُجْزِئُكَ مِنْ ذَلِكَ الْوُضُوءُ قَالَ قُلْتُ فَكَيْفَ بِمَا يُصِيبُ ثَوْبِي مِنْهُ قَالَ خُذْ كَفًّا مِنْ مَاءٍ ‏ ‏فَانْضَحْهُ ‏ ‏حَيْثُ ‏ ‏تَرَى أَنَّهُ أَصَابَهُ ‏","","",""],[718,718,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ حَزْمٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُسْرَةَ بِنْتِ صَفْوَانَ ‏ ‏أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَتَوَضَّأُ الرَّجُلُ مِنْ مَسِّ الذَّكَرِ ‏","","",""],[719,719,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ الْوَهْبِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏بُسْرَةَ بِنْتِ صَفْوَانَ ‏ ‏أَنَّهَا سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا أَوْثَقُ فِي مَسِّ الْفَرْجِ وَقَالَ الْوُضُوءُ أَثْبَتُ ‏","","",""],[720,720,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏خَارِجَةَ بْنَ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْوُضُوءُ مِمَّا مَسَّتْ النَّارُ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَأْخُذُ بِهِ ‏ ‏قَالَ ‏ ‏لَا ‏","","",""],[721,721,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏عَمْرَو بْنَ أُمَيَّةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَزُّ ‏ ‏مِنْ كَتِفِ شَاةٍ فِي يَدِهِ ثُمَّ دُعِيَ إِلَى الصَّلَاةِ فَأَلْقَى السِّكِّينَ الَّتِي كَانَ ‏ ‏يَحْتَزُّ ‏ ‏بِهَا ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[722,722,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَسَنُ بْنُ أَحْمَدَ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏الْجُلَاحِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى رِجَالٌ مِنْ ‏ ‏بَنِي مُدْلِجٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا أَصْحَابُ هَذَا الْبَحْرِ ‏ ‏نُعَالِجُ ‏ ‏الصَّيْدَ عَلَى ‏ ‏رَمَثٍ ‏ ‏فَنَعْزُبُ ‏ ‏فِيهِ اللَّيْلَةَ وَاللَّيْلَتَيْنِ وَالثَّلَاثَ وَالْأَرْبَعَ وَنَحْمِلُ مَعَنَا مِنْ ‏ ‏الْعَذْبِ ‏ ‏لِشِفَاهِنَا ‏ ‏فَإِنْ نَحْنُ تَوَضَّأْنَا بِهِ خَشِينَا عَلَى أَنْفُسِنَا وَإِنْ نَحْنُ آثَرْنَا بِأَنْفُسِنَا وَتَوَضَّأْنَا مِنْ الْبَحْرِ وَجَدْنَا فِي أَنْفُسِنَا مِنْ ذَلِكَ فَخَشِينَا أَنْ لَا يَكُونَ طَهُورًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِنْهُ فَإِنَّهُ الطَّاهِرُ مَاؤُهُ الْحَلَالُ مَيْتَتُهُ ‏","","",""],[723,723,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قِرَاءَةً ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ ‏ ‏مِنْ آلِ ‏ ‏الْأَزْرَقِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بُرْدَةَ ‏ ‏وَهُوَ رَجُلٌ مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّا نَرْكَبُ الْبَحْرَ وَمَعَنَا الْقَلِيلُ مِنْ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏","","",""],[724,724,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولُ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَغْتَسِلُ مِنْهُ ‏","","",""],[725,725,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُسْأَلُ عَنْ الْمَاءِ يَكُونُ ‏ ‏بِالْفَلَاةِ ‏ ‏مِنْ الْأَرْضِ وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ ‏ ‏إِذَا بَلَغَ الْمَاءُ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يُنَجِّسْهُ شَيْءٌ ‏","","",""],[726,726,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الْمَاءِ وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يَحْمِلْ الْخَبَثَ ‏","","",""],[727,727,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏وَأَبُو زَيْدٍ سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏جَاءَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُنِي ‏ ‏وَأَنَا مَرِيضٌ لَا أَعْقِلُ ‏ ‏فَتَوَضَّأَ وَصَبَّ مِنْ وَضُوئِهِ عَلَيَّ فَعَقَلْتُ ‏","","",""],[728,728,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَامَتْ امْرَأَةٌ مِنْ نِسَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاغْتَسَلَتْ فِي ‏ ‏جَفْنَةٍ ‏ ‏مِنْ جَنَابَةٍ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى فَضْلِهَا يَسْتَحِمُّ فَقَالَتْ إِنِّي قَدْ اغْتَسَلْتُ فِيهِ قَبْلَكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَيْسَ عَلَى الْمَاءِ جَنَابَةٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[729,729,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدَةَ بِنْتِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ ‏ ‏وَكَانَتْ تَحْتَ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏دَخَلَ عَلَيْهَا فَسَكَبَتْ لَهُ وَضُوءًا فَجَاءَتْ هِرَّةٌ تَشْرَبُ مِنْهُ ‏ ‏فَأَصْغَى ‏ ‏لَهَا ‏ ‏أَبُو قَتَادَةَ ‏ ‏الْإِنَاءَ حَتَّى شَرِبَتْ قَالَتْ ‏ ‏كَبْشَةُ ‏ ‏فَرَآنِي أَنْظُرُ فَقَالَ أَتَعْجَبِينَ يَا بِنْتَ أَخِي قُلْتُ نَعَمْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّمَا هِيَ مِنْ الطَّوَّافِينَ عَلَيْكُمْ وَالطَّوَّافَاتِ ‏","","",""],[730,730,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مِرَارٍ وَالثَّامِنَةَ ‏ ‏عَفِّرُوهُ ‏ ‏فِي التُّرَابِ ‏","","",""],[731,731,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ فَأْرَةً وَقَعَتْ فِي سَمْنٍ فَمَاتَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْقُوهَا وَمَا حَوْلَهَا وَكُلُوهُ ‏","","",""],[732,732,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَبْرَيْنِ فَقَالَ ‏ ‏إِنَّهُمَا لَيُعَذَّبَانِ فِي قُبُورِهِمَا وَمَا يُعَذَّبَانِ فِي كَبِيرٍ كَانَ أَحَدُهُمَا يَمْشِي بِالنَّمِيمَةِ وَكَانَ الْآخَرُ لَا ‏ ‏يَسْتَنْزِهُ ‏ ‏عَنْ الْبَوْلِ ‏ ‏أَوْ مِنْ الْبَوْلِ ‏ ‏قَالَ ثُمَّ أَخَذَ ‏ ‏جَرِيدَةً ‏ ‏رَطْبَةً فَكَسَرَهَا فَغَرَزَ عِنْدَ رَأْسِ كُلِّ قَبْرٍ مِنْهُمَا قِطْعَةً ثُمَّ قَالَ عَسَى أَنْ يُخَفَّفَ عَنْهُمَا حَتَّى تَيْبَسَا ‏","","",""],[733,733,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا قَامَ ‏ ‏بَالَ فِي نَاحِيَةِ الْمَسْجِدِ قَالَ فَصَاحَ بِهِ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَفَّهُمْ عَنْهُ ثُمَّ دَعَا بِدَلْوٍ مِنْ مَاءٍ فَصَبَّهُ عَلَى بَوْلِهِ ‏","","",""],[734,734,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏وَحَدَّثَنَاهُ عَنْ ‏ ‏يُونُسَ ‏ ‏أَيْضًا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏أَنَّهَا ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لَهَا لَمْ يَبْلُغْ أَنْ يَأْكُلَ الطَّعَامَ فَأَجْلَسَتْهُ فِي حِجْرِهِ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ ‏ ‏فَنَضَحَهُ ‏ ‏وَلَمْ يَغْسِلْهُ ‏","","",""],[735,735,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ وَلَدٍ لِإِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهَا سَأَلَتْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي امْرَأَةٌ أُطِيلُ ‏ ‏ذَيْلِي ‏ ‏فَأَمْشِي فِي الْمَكَانِ الْقَذِرِ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطَهِّرُهُ مَا بَعْدَهُ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَأْخُذُ بِهَذَا ‏ ‏قَالَ ‏ ‏لَا أَدْرِي ‏","","",""],[736,736,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو رَجَاءٍ الْعُطَارِدِيُّ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ثُمَّ نَزَلَ فَدَعَا بِوَضُوءٍ فَتَوَضَّأَ ثُمَّ نُودِيَ بِالصَّلَاةِ فَصَلَّى بِالنَّاسِ فَلَمَّا ‏ ‏انْفَتَلَ ‏ ‏مِنْ صَلَاتِهِ إِذَا هُوَ بِرَجُلٍ مُعْتَزِلٍ لَمْ يُصَلِّ فِي الْقَوْمِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَنَعَكَ يَا فُلَانُ أَنْ تُصَلِّيَ فِي الْقَوْمِ فَقَالَ يَا رَسُولَ اللَّهِ أَصَابَتْنِي جَنَابَةٌ وَلَا مَاءَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكَ ‏ ‏بِالصَّعِيدِ ‏ ‏فَإِنَّهُ يَكْفِيكَ ‏","","",""],[737,737,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏اللَّيْثِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ رَجُلَانِ فِي سَفَرٍ فَحَضَرَتْهُمَا الصَّلَاةُ وَلَيْسَ مَعَهُمَا مَاءٌ فَتَيَمَّمَا ‏ ‏صَعِيدًا ‏ ‏طَيِّبًا فَصَلَّيَا ثُمَّ وَجَدَا الْمَاءَ بَعْدُ فِي الْوَقْتِ فَأَعَادَ أَحَدُهُمَا الصَّلَاةَ بِوُضُوءٍ وَلَمْ يُعِدْ الْآخَرُ ثُمَّ أَتَيَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَا ذَلِكَ فَقَالَ لِلَّذِي لَمْ يُعِدْ ‏ ‏أَصَبْتَ السُّنَّةَ وَأَجْزَتْكَ صَلَاتُكَ وَقَالَ لِلَّذِي تَوَضَّأَ وَأَعَادَ لَكَ الْأَجْرُ مَرَّتَيْنِ ‏","","",""],[738,738,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي التَّيَمُّمِ ‏ ‏ضَرْبَةٌ لِلْوَجْهِ وَالْكَفَّيْنِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏صَحَّ إِسْنَادُهُ ‏","","",""],[739,739,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا اسْتَعَارَتْ قِلَادَةً مِنْ ‏ ‏أَسْمَاءَ ‏ ‏فَهَلَكَتْ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاسًا مِنْ أَصْحَابِهِ فِي طَلَبِهَا فَأَدْرَكَتْهُمْ الصَّلَاةُ فَصَلَّوْا مِنْ غَيْرِ وُضُوءٍ فَلَمَّا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَكَوْا ذَلِكَ إِلَيْهِ فَنَزَلَتْ ‏ ‏آيَةُ التَّيَمُّمِ ‏ ‏فَقَالَ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏جَزَاكِ اللَّهُ خَيْرًا فَوَاللَّهِ مَا نَزَلَ بِكِ أَمْرٌ قَطُّ إِلَّا جَعَلَ اللَّهُ لَكِ مِنْهُ مَخْرَجًا وَجَعَلَ لِلْمُسْلِمِينَ فِيهِ بَرَكَةً ‏","","",""],[740,740,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاءً فَأَفْرَغَ عَلَى يَدَيْهِ فَجَعَلَ يَغْسِلُ بِهَا فَرْجَهُ فَلَمَّا فَرَغَ مَسَحَهَا بِالْأَرْضِ ‏ ‏أَوْ بِحَائِطٍ شَكَّ ‏ ‏سُلَيْمَانُ ‏ ‏ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ فَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ وَصَبَّ عَلَى رَأْسِهِ وَجَسَدِهِ فَلَمَّا فَرَغَ تَنَحَّى فَغَسَلَ رِجْلَيْهِ فَأَعْطَيْتُهُ مِلْحَفَةً فَأَبَى وَجَعَلَ يَنْفُضُ بِيَدِهِ قَالَتْ فَسَتَرْتُهُ حَتَّى اغْتَسَلَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَذَكَرَ ‏ ‏سَالِمٌ ‏ ‏أَنَّ غُسْلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا كَانَ مِنْ جَنَابَةٍ ‏","","",""],[741,741,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْدَأُ ‏ ‏فَيَغْسِلُ يَدَيْهِ ثُمَّ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يُدْخِلُ كَفَّهُ فِي الْمَاءِ ‏ ‏فَيُخَلِّلُ ‏ ‏بِهَا أُصُولَ شَعْرِهِ حَتَّى إِذَا خُيِّلَ إِلَيْهِ أَنَّهُ قَدْ اسْتَبْرَأَ الْبَشَرَةَ غَرَفَ بِيَدِهِ ثَلَاثَ غَرَفَاتٍ فَصَبَّهَا عَلَى رَأْسِهِ ثُمَّ اغْتَسَلَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا أَحَبُّ إِلَيَّ مِنْ حَدِيثِ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏","","",""],[742,742,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏","","",""],[743,743,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَهُوَ ‏ ‏الْفَرَقُ ‏","","",""],[744,744,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ مَوْضِعَ شَعْرَةٍ مِنْ جَنَابَةٍ لَمْ يُصِبْهَا الْمَاءُ فُعِلَ بِهَا كَذَا وَكَذَا مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏فَمِنْ ثَمَّ عَادَيْتُ رَأْسِي وَكَانَ ‏ ‏يَجُزُّ ‏ ‏شَعْرَهُ ‏","","",""],[745,745,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏قَالَ إِنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُخْبِرُ ‏ ‏أَنَّ رَجُلًا أَصَابَهُ جُرْحٌ فِي عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَصَابَهُ احْتِلَامٌ فَأُمِرَ ‏ ‏بِالِاغْتِسَالِ فَمَاتَ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏قَتَلُوهُ قَتَلَهُمْ اللَّهُ أَلَمْ يَكُنْ شِفَاءَ ‏ ‏الْعِيِّ ‏ ‏السُّؤَالُ ‏ ‏وَقَالَ ‏ ‏عَطَاءٌ ‏ ‏بَلَغَنِي أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ بَعْدَ ذَلِكَ فَقَالَ لَوْ غَسَلَ جَسَدَهُ وَتَرَكَ رَأْسَهُ حَيْثُ أَصَابَهُ الْجُرْحُ ‏","","",""],[746,746,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ ‏ ‏عَلَى نِسَائِهِ فِي يَوْمٍ وَاحِدٍ ‏","","",""],[747,747,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ ‏ ‏عَلَى نِسَائِهِ فِي لَيْلَةٍ وَاحِدَةٍ ‏ ‏جُمَعَ ‏","","",""],[748,748,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَرْدَفَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ خَلْفَهُ فَأَسَرَّ إِلَيَّ حَدِيثًا لَا أُحَدِّثُ بِهِ أَحَدًا مِنْ النَّاسِ وَكَانَ أَحَبَّ مَا اسْتَتَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ‏ ‏هَدَفٌ ‏ ‏أَوْ ‏ ‏حَائِشُ ‏ ‏نَخْلٍ ‏","","",""],[749,749,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تُصِيبُنِي الْجَنَابَةُ مِنْ اللَّيْلِ فَأَمَرَهُ أَنْ ‏ ‏يَغْسِلَ ذَكَرَهُ وَيَتَوَضَّأَ ثُمَّ يَرْقُدَ ‏","","",""],[750,750,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ فَقَالَتْ كَانَ ‏ ‏يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يَنَامُ ‏","","",""],[751,751,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سُعَادٍ ‏ ‏وَكَانَ مَرْضِيًّا مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏","","",""],[752,752,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَمِعَ مِنْهُ وَهُوَ ابْنُ خَمْسَ عَشْرَةَ سَنَةً حِينَ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنِي ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏أَنَّ الْفُتْيَا الَّتِي كَانُوا يُفْتَوْنَ بِهَا فِي قَوْلِهِ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏ ‏رُخْصَةٌ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِيهَا فِي أَوَّلِ الْإِسْلَامِ ثُمَّ أَمَرَ ‏ ‏بِالِاغْتِسَالِ بَعْدُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و قَالَ ‏ ‏غَيْرُهُ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏بَعْضُ مَنْ أَرْضَى ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏","","",""],[753,753,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ مِهْرَانَ الْجَمَّالُ ‏ ‏حَدَّثَنَا ‏ ‏مُبَشِّرٌ الْحَلَبِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ أَبِي غَسَّانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أُبَيٌّ ‏ ‏أَنَّ الْفُتْيَا الَّتِي كَانُوا يُفْتَوْنَ بِهَا ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏ ‏كَانَتْ رُخْصَةً رَخَّصَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَوَّلِ الْإِسْلَامِ ‏ ‏أَوْ الزَّمَانِ ‏ ‏ثُمَّ اغْتَسَلَ بَعْدُ ‏","","",""],[754,754,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ شُعَبِهَا الْأَرْبَعِ ثُمَّ ‏ ‏جَهَدَهَا ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[755,755,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ ‏ ‏سَأَلَتْ خَالَتِي ‏ ‏خَوْلَةُ بِنْتُ حَكِيمٍ الْسُلَمِيَّةُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَرْأَةِ تَحْتَلِمُ فَأَمَرَهَا أَنْ تَغْتَسِلَ ‏","","",""],[756,756,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏أُمَّ ‏ ‏بَنِي أَبِي طَلْحَةَ ‏ ‏دَخَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ أَرَأَيْتَ الْمَرْأَةَ ‏ ‏تَرَى فِي النَّوْمِ مَا يَرَى الرَّجُلُ أَتَغْتَسِلُ قَالَ نَعَمْ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ أُفٍّ لَكِ أَتَرَى الْمَرْأَةُ ذَلِكَ فَالْتَفَتَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ فَمِنْ أَيْنَ يَكُونُ الشَّبَهُ ‏","","",""],[757,757,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَخَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏وَعِنْدَهُ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَقَالَتْ الْمَرْأَةُ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكِ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏فَضَحْتِ النِّسَاءَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْتَصِرًا ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏بَلْ أَنْتِ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكِ إِنَّ خَيْرَكُنَّ الَّتِي تَسْأَلُ عَمَّا ‏ ‏يَعْنِيهَا إِذَا رَأَتْ الْمَاءَ فَلْتَغْتَسِلْ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏وَلِلنِّسَاءِ مَاءٌ قَالَ نَعَمْ فَأَنَّى يُشْبِهُهُنَّ الْوَلَدُ إِنَّمَا هُنَّ شَقَائِقُ الرِّجَالِ ‏","","",""],[758,758,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَوْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ يَسْتَيْقِظُ فَيَرَى بَلَلًا وَلَمْ يَذْكُرْ احْتِلَامًا قَالَ ‏ ‏لِيَغْتَسِلْ فَإِنْ رَأَى احْتِلَامًا وَلَمْ يَرَ بَلَلًا فَلَا غُسْلَ عَلَيْهِ ‏","","",""],[759,759,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلَا يَغْمِسْ يَدَهُ فِي الْوَضُوءِ حَتَّى يَغْسِلَهَا ثَلَاثًا ‏","","",""],[760,760,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ ‏ ‏الْغَائِطَ ‏ ‏ثُمَّ خَرَجَ فَأُتِيَ بِطَعَامٍ فَقِيلَ أَلَا تَتَوَضَّأُ فَقَالَ ‏ ‏أُصَلِّي فَأَتَوَضَّأُ ‏","","",""],[761,761,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏وَهِيَ تَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏سَبْعَ سِنِينَ فَشَكَتْ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ لَيْسَتْ بِالْحَيْضَةِ وَإِنَّمَا هِيَ عِرْقٌ فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَدَعِي الصَّلَاةَ وَإِذَا أَدْبَرَتْ فَاغْتَسِلِي ثُمَّ صَلِّي ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ ثُمَّ تُصَلِّي وَكَانَتْ تَقْعُدُ فِي ‏ ‏مِرْكَنٍ ‏ ‏لِأُخْتِهَا ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏حَتَّى إِنَّ حُمْرَةَ الدَّمِ ‏ ‏لَتَعْلُو الْمَاءَ ‏","","",""],[762,762,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ صَاحِبِ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[763,763,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو حَاتِمٍ الْبَصْرِيُّ رَوْحُ بْنُ أَسْلَمَ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[764,764,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ إِنِّي حَائِضٌ قَالَ إِنَّهَا لَيْسَتْ فِي يَدِكِ ‏","","",""],[765,765,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏جَدَّتِهَا ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ امْرَأَةً وَهِيَ تَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ تَصْنَعُ بِثَوْبِهَا إِذَا طَهُرَتْ مِنْ مَحِيضِهَا قَالَ ‏ ‏إِنْ رَأَيْتِ فِيهِ دَمًا فَحُكِّيهِ ثُمَّ اقْرُصِيهِ ثُمَّ ‏ ‏انْضَحِي ‏ ‏فِي سَائِرِ ثَوْبِكِ ثُمَّ صَلِّي فِيهِ ‏","","",""],[766,766,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏سَأَلَتْ امْرَأَةٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحَيْضِ قَالَ ‏ ‏خُذِي مَاءَكِ ‏ ‏وَسِدْرَكِ ‏ ‏ثُمَّ اغْتَسِلِي وَأَنْقِي ثُمَّ صُبِّي عَلَى رَأْسِكِ حَتَّى تَبْلُغِي ‏ ‏شُؤُونَ ‏ ‏الرَّأْسِ ثُمَّ خُذِي ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏قَالَتْ كَيْفَ أَصْنَعُ بِهَا يَا رَسُولَ اللَّهِ فَسَكَتَ قَالَتْ فَكَيْفَ أَصْنَعُ بِهَا يَا رَسُولَ اللَّهِ فَسَكَتَ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏خُذِي ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَتَتَبَّعِي بِهَا آثَارَ الدَّمِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْمَعُ فَمَا أَنْكَرَ عَلَيْهَا ‏","","",""],[767,767,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ ‏ ‏أُسْتَحَاضُ ‏ ‏فَلَا أَطْهُرُ أَفَأَدَعُ الصَّلَاةَ قَالَ ‏ ‏لَا إِنَّمَا ذَلِكِ عِرْقٌ فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَدَعِي الصَّلَاةَ وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ وَصَلِّي ‏","","",""],[768,768,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏ابْنَةَ جَحْشٍ ‏ ‏اسْتُحِيضَتْ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْغُسْلِ لِكُلِّ صَلَاةٍ فَإِنْ كَانَتْ لَتَدْخُلُ ‏ ‏الْمِرْكَنَ ‏ ‏وَإِنَّهُ لَمَمْلُوءٌ مَاءً فَتَنْغَمِسُ فِيهِ ثُمَّ تَخْرُجُ مِنْهُ وَإِنَّ الدَّمَ لَعَالِيهِ فَتُصَلِّي ‏","","",""],[769,769,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّمَا هِيَ فُلَانَةُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏أَمَرَهَا بِالْغُسْلِ لِكُلِّ صَلَاةٍ فَلَمَّا شَقَّ ذَلِكَ عَلَيْهَا أَمَرَهَا أَنْ تَجْمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ بِغُسْلٍ وَاحِدٍ وَبَيْنَ الْمَغْرِبِ وَالْعِشَاءِ بِغُسْلٍ وَاحِدٍ وَتَغْتَسِلَ لِلْفَجْرِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏النَّاسُ يَقُولُونَ ‏ ‏سَهْلَةُ بِنْتُ سُهَيْلٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏سُهَيْلَةُ بِنْتُ سَهْلٍ ‏","","",""],[770,770,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏فَأَخْبَرَنِي عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً ‏ ‏اسْتُحِيضَتْ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُمِرَتْ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهَا قَالَ لَا أُحَدِّثُكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا ‏ ‏فَأُمِرَتْ أَنْ تُؤَخِّرَ الظُّهْرَ وَتُعَجِّلَ الْعَصْرَ وَتَغْتَسِلَ لَهُمَا غُسْلًا وَتُؤَخِّرَ الْمَغْرِبَ وَتُعَجِّلَ الْعِشَاءَ وَتَغْتَسِلَ لَهُمَا غُسْلًا وَتَغْتَسِلَ لِلصُّبْحِ غُسْلًا ‏","","",""],[771,771,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏سَبْعَ سِنِينَ وَهِيَ تَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏فَاشْتَكَتْ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا لَيْسَتْ بِحِيضَةٍ إِنَّمَا هُوَ عِرْقٌ فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَدَعِي الصَّلَاةَ وَإِذَا أَدْبَرَتْ فَاغْتَسِلِي وَصَلِّي قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ ثُمَّ تُصَلِّي قَالَتْ وَكَانَتْ تَقْعُدُ فِي ‏ ‏مِرْكَنٍ ‏ ‏لِأُخْتِهَا ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏حَتَّى إِنَّ حُمْرَةَ الدَّمِ ‏ ‏لَتَعْلُو الْمَاءَ ‏","","",""],[772,772,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ ‏ ‏أُسْتَحَاضُ ‏ ‏أَفَأَتْرُكُ الصَّلَاةَ قَالَ ‏ ‏لَا إِنَّمَا ذَلِكِ عِرْقٌ وَلَيْسَتْ بِالْحِيضَةِ فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَاتْرُكِي الصَّلَاةَ فَإِذَا ذَهَبَ قَدْرُهَا فَاغْسِلِي عَنْكِ الدَّمَ وَتَوَضَّئِي وَصَلِّي ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏فَكَانَ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏تَغْتَسِلُ غُسْلَ الْأَوَّلِ ثُمَّ مَا يَكُونُ بَعْدَ ذَلِكَ فَإِنَّهَا تَطَّهَّرُ وَتُصَلِّي ‏","","",""],[773,773,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ امْرَأَةً كَانَتْ ‏ ‏تُهَرَاقُ ‏ ‏الدَّمَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَفْتَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏لَهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏لِتَنْظُرْ عَدَدَ اللَّيَالِي وَالْأَيَّامِ الَّتِي كَانَتْ تَحِيضُهُنَّ قَبْلَ أَنْ يَكُونَ بِهَا الَّذِي كَانَ وَقَدْرَهُنَّ مِنْ الشَّهْرِ فَتَتْرُكْ الصَّلَاةَ لِذَلِكَ فَإِذَا خَلَفَتْ ذَلِكَ وَحَضَرَتْ الصَّلَاةُ فَلْتَغْتَسِلْ ‏ ‏وَلْتَسْتَثْفِرْ ‏ ‏بِثَوْبٍ ثُمَّ تُصَلِّي ‏","","",""],[774,774,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ غَلَبَنِي الدَّمُ قَالَ ‏ ‏اغْتَسِلِي وَصَلِّي ‏","","",""],[775,775,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ ‏ ‏أَنَّهَا سَمِعَتْ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏جَاءَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏سَبْعَ سِنِينَ فَاشْتَكَتْ ذَلِكَ إِلَيْهِ وَاسْتَفْتَتْهُ فِيهِ فَقَالَ لَهَا ‏ ‏إِنَّ هَذَا لَيْسَ بِالْحِيضَةِ إِنَّمَا هَذَا عِرْقٌ فَاغْتَسِلِي ثُمَّ صَلِّي ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَكَانَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏تَغْتَسِلُ لِكُلِّ صَلَاةٍ وَتُصَلِّي وَكَانَتْ تَجْلِسُ فِي ‏ ‏الْمِرْكَنِ ‏ ‏فَتَعْلُو حُمْرَةُ الدَّمِ الْمَاءَ ثُمَّ تُصَلِّي ‏","","",""],[776,776,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏كَانَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْغُسْلِ لِكُلِّ صَلَاةٍ فَإِنْ كَانَتْ لَتَنْغَمِسُ فِي ‏ ‏الْمِرْكَنِ ‏ ‏وَإِنَّهُ لَمَمْلُوءٌ مَاءً ثُمَّ تَخْرُجُ مِنْهُ وَإِنَّ الدَّمَ لَعَالِيهِ فَتُصَلِّي ‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏بَادِيَةَ بِنْتَ غَيْلَانَ الثَّقَفِيَّةَ ‏ ‏وَعَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّمَا هِيَ ‏ ‏سَهْلَةُ بِنْتُ سُهَيْلِ بْنِ عَمْرٍو ‏ ‏اسْتُحِيضَتْ ‏ ‏وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَمَرَهَا بِالْغُسْلِ عِنْدَ كُلِّ صَلَاةٍ فَلَمَّا ‏ ‏جَهَدَهَا ‏ ‏ذَلِكَ أَمَرَ أَنْ تَجْمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ فِي غُسْلٍ وَاحِدٍ وَالْمَغْرِبِ وَالْعِشَاءِ فِي غُسْلٍ وَاحِدٍ وَتَغْتَسِلَ لِلصُّبْحِ ‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا جَاءَ اخْتِلَافُهُمْ أَنَّهُنَّ ثَلَاثَتَهُنَّ كُنَّ عِنْدَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏فَقَالَ بَعْضُهُمْ هِيَ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏وَقَالَ بَعْضُهُمْ هِيَ ‏ ‏بَادِيَةُ ‏ ‏وَقَالَ بَعْضُهُمْ هِيَ ‏ ‏سَهْلَةُ بِنْتُ سُهَيْلٍ ‏","","",""],[777,777,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏الْقَعْقَاعَ بْنَ حَكِيمٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏سَعِيدًا ‏ ‏عَنْ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏فَقَالَ يَا ابْنَ أَخِي مَا بَقِيَ أَحَدٌ أَعْلَمُ بِهَذَا مِنِّي ‏ ‏إِذَا أَقْبَلَتْ الْحَيْضَةُ فَلْتَدَعْ الصَّلَاةَ وَإِذَا أَدْبَرَتْ فَلْتَغْتَسِلْ وَلْتُصَلِّ ‏","","",""],[778,778,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَدَعُ الصَّلَاةَ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏ثُمَّ تَغْتَسِلُ ثُمَّ ‏ ‏تَحْتَشِي ‏ ‏وَتَسْتَثْفِرُ ‏ ‏ثُمَّ تُصَلِّي فَقَالَ الرَّجُلُ وَإِنْ كَانَ يَسِيلُ قَالَ وَإِنْ كَانَ يَسِيلُ مِثْلَ هَذَا ‏ ‏الْمَثْعَبِ ‏","","",""],[779,779,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مِنْ أَشَدِّ النَّاسِ قَوْلًا فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏ثُمَّ رَخَّصَ بَعْدُ أَتَتْهُ امْرَأَةٌ فَقَالَتْ أَدْخُلُ ‏ ‏الْكَعْبَةَ ‏ ‏وَأَنَا حَائِضٌ قَالَ نَعَمْ وَإِنْ كُنْتِ ‏ ‏تَثُجِّينَهُ ‏ ‏ثَجًّا ‏ ‏اسْتَدْخِلِي ثُمَّ ‏ ‏اسْتَثْفِرِي ‏ ‏ثُمَّ ادْخُلِي ‏","","",""],[780,780,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏قَمِيرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُهَا عَنْ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏قَالَتْ ‏ ‏تَنْتَظِرُ ‏ ‏أَقْرَاءَهَا ‏ ‏الَّتِي كَانَتْ تَتْرُكُ فِيهَا الصَّلَاةَ قَبْلَ ذَلِكَ فَإِذَا كَانَ يَوْمُ طُهْرِهَا الَّذِي كَانَتْ تَطْهُرُ فِيهِ اغْتَسَلَتْ ثُمَّ تَوَضَّأَتْ عِنْدَ كُلِّ صَلَاةٍ وَصَلَّتْ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُعْتَمِرٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏حَيِّهِ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏مِثْلَ مَا قَالَتْ ‏ ‏عَائِشَةُ ‏","","",""],[781,781,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏قَمِيرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَنْتَظِرُ أَيَّامَهَا الَّتِي كَانَتْ تَتْرُكُ الصَّلَاةَ فِيهَا فَإِذَا كَانَ يَوْمُ طُهْرِهَا الَّذِي كَانَتْ تَطْهُرُ فِيهِ اغْتَسَلَتْ ثُمَّ تَوَضَّأَتْ عِنْدَ كُلِّ صَلَاةٍ وَصَلَّتْ ‏","","",""],[782,782,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي الْيَقْظَانِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَدَعُ الصَّلَاةَ أَيَّامَ حَيْضِهَا فِي كُلِّ شَهْرٍ فَإِذَا كَانَ عِنْدَ انْقِضَائِهَا اغْتَسَلَتْ وَصَلَّتْ وَصَامَتْ وَتَوَضَّأَتْ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[783,783,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏كَثِيرٍ ‏ ‏وَحَفْصٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏إِذَا طُلِّقَتْ فَيَطُولُ بِهَا الدَّمُ فَإِنَّهَا تَعْتَدُّ قَدْرَ ‏ ‏أَقْرَائِهَا ‏ ‏ثَلَاثَ حِيَضٍ وَفِي الصَّلَاةِ إِذَا جَاءَ وَقْتُ الْحَيْضِ فِي كُلِّ شَهْرٍ أَمْسَكَتْ عَنْ الصَّلَاةِ ‏","","",""],[784,784,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏امْرَأَةٌ كَانَ حَيْضُهَا مَعْلُومًا فَزَادَتْ عَلَيْهِ خَمْسَةَ أَيَّامٍ أَوْ أَرْبَعَةَ أَيَّامٍ أَوْ ثَلَاثَةَ أَيَّامٍ ‏ ‏قَالَ ‏ ‏تُصَلِّي قُلْتُ يَوْمَيْنِ قَالَ ذَاكَ مِنْ حَيْضِهَا ‏ ‏وَسَأَلْتُ ‏ ‏ابْنَ سِيرِينَ ‏ ‏قَالَ ‏ ‏النِّسَاءُ أَعْلَمُ بِذَلِكَ ‏","","",""],[785,785,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْمَرْأَةِ ‏ ‏تَرَى الدَّمَ أَيَّامَ طُهْرِهَا قَالَ ‏ ‏أَرَى أَنْ تَغْتَسِلَ وَتُصَلِّيَ ‏","","",""],[786,786,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ الْمَرْأَةِ ‏ ‏تُسْتَحَاضُ ‏ ‏قَالَ ‏ ‏تَنْتَظِرُ قَدْرَ مَا كَانَتْ تَحِيضُ فَلْتُحَرِّمْ الصَّلَاةَ ثُمَّ لِتَغْتَسِلْ وَلْتُصَلِّ حَتَّى إِذَا كَانَ أَوَانُهَا الَّذِي تَحِيضُ فِيهِ فَلْتُحَرِّمْ الصَّلَاةَ ثُمَّ لِتَغْتَسِلْ فَإِنَّمَا ذَاكَ مِنْ الشَّيْطَانِ يُرِيدُ أَنْ يُكْفِرَ إِحْدَاهُنَّ ‏","","",""],[787,787,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ أَبِي جَعْفَرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَدَعُ الصَّلَاةَ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏ثُمَّ تَغْتَسِلُ ‏ ‏وَتَحْتَشِي ‏ ‏كُرْسُفًا ‏ ‏وَتَوَضَّأُ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[788,788,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏قَمِيرَ ‏ ‏امْرَأَةِ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَجْلِسُ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏ثُمَّ تَغْتَسِلُ غُسْلًا وَاحِدًا وَتَتَوَضَّأُ لِكُلِّ صَلَاةٍ ‏","","",""],[789,789,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏اسْتُحِيضَتْ ‏ ‏امْرَأَةٌ مِنْ آلِ ‏ ‏أَنَسٍ ‏ ‏فَأَمَرُونِي فَسَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏أَمَّا مَا رَأَتْ الدَّمَ ‏ ‏الْبَحْرَانِيَّ ‏ ‏فَلَا تُصَلِّي فَإِذَا رَأَتْ الطُّهْرَ وَلَوْ سَاعَةً مِنْ نَهَارٍ فَلْتَغْتَسِلْ وَلْتُصَلِّ ‏","","",""],[790,790,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏كَانَتْ أُمُّ وَلَدٍ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏اسْتُحِيضَتْ ‏ ‏فَأَمَرُونِي أَنْ أَسْتَفْتِيَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَسَأَلْتُهُ فَقَالَ ‏ ‏إِذَا رَأَتْ الدَّمَ ‏ ‏الْبَحْرَانِيَّ ‏ ‏فَلَا تُصَلِّي فَإِذَا رَأَتْ الطُّهْرَ فَلْتَغْتَسِلْ وَلْتُصَلِّ ‏","","",""],[791,791,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ نُصَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْهُ فَقَالَتْ إِنِّي امْرَأَةٌ ‏ ‏أُسْتَحَاضُ ‏ ‏فَقَالَ إِذَا رَأَيْتِ دَمًا ‏ ‏عَبِيطًا ‏ ‏فَأَمْسِكِي أَيَّامَ ‏ ‏أَقْرَائِكِ ‏","","",""],[792,792,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَجْلِسُ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏ثُمَّ تَغْتَسِلُ لِلظُّهْرِ وَالْعَصْرِ غُسْلًا وَاحِدًا وَتُؤَخِّرُ الْمَغْرِبَ وَتُعَجِّلُ الْعِشَاءَ وَذَلِكَ فِي وَقْتِ الْعِشَاءِ وَلِلْفَجْرِ غُسْلًا وَاحِدًا وَلَا تَصُومُ وَلَا يَأْتِيهَا زَوْجُهَا وَلَا تَمَسُّ الْمُصْحَفَ ‏","","",""],[793,793,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَسَنُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ غُسْلًا وَاحِدًا لِلظُّهْرِ وَالْعَصْرِ وَغُسْلًا لِلْمَغْرِبِ وَالْعِشَاءِ وَكَانَ يَقُولُ تُؤَخِّرُ الظُّهْرَ وَتُعَجِّلُ الْعَصْرَ وَتُؤَخِّرُ الْمَغْرِبَ وَتُعَجِّلُ الْعِشَاءَ ‏","","",""],[794,794,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏إِذَا خَلَفَتْ ‏ ‏قُرُوءَهَا ‏ ‏فَإِذَا كَانَ عِنْدَ الْعَصْرِ تَوَضَّأَتْ وُضُوءًا ‏ ‏سَابِغًا ‏ ‏ثُمَّ لِتَأْخُذْ ثَوْبًا ‏ ‏فَلْتَسْتَثْفِرْ ‏ ‏بِهِ ثُمَّ لِتُصَلِّ الظُّهْرَ وَالْعَصْرَ جَمِيعًا ثُمَّ لِتَفْعَلْ مِثْلَ ذَلِكَ ثُمَّ لِتُصَلِّ الْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا ثُمَّ لِتَفْعَلْ مِثْلَ ذَلِكَ ثُمَّ تُصَلِّي الصُّبْحَ ‏","","",""],[795,795,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَسَعِيدٍ ‏ ‏وَعِكْرِمَةَ ‏ ‏قَالُوا ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ كُلَّ يَوْمٍ لِصَلَاةِ الْأُولَى وَالْعَصْرِ ‏ ‏فَتُصَلِّيهِمَا وَتَغْتَسِلُ لِلْمَغْرِبِ وَالْعِشَاءِ ‏ ‏فَتُصَلِّيهِمَا وَتَغْتَسِلُ لِصَلَاةِ ‏ ‏الْغَدَاةِ ‏","","",""],[796,796,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَغْتَسِلُ ثُمَّ تَجْمَعُ بَيْنَ الظُّهْرِ وَالْعَصْرِ فَإِنْ رَأَتْ شَيْئًا اغْتَسَلَتْ وَجَمَعَتْ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[797,797,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏فَقَالَ ‏ ‏تَجْلِسُ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏وَتَغْتَسِلُ مِنْ الظُّهْرِ إِلَى الظُّهْرِ ‏ ‏وَتَسْتَذْفِرُ ‏ ‏بِثَوْبٍ وَيَأْتِيهَا زَوْجُهَا وَتَصُومُ فَقُلْتُ عَمَّنْ هَذَا فَأَخَذَ الْحَصَا ‏","","",""],[798,798,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏تَغْتَسِلُ مِنْ ظُهْرٍ إِلَى ظُهْرٍ وَتَتَوَضَّأُ لِكُلِّ صَلَاةٍ فَإِنْ غَلَبَهَا الدَّمُ ‏ ‏اسْتَثْفَرَتْ ‏ ‏وَكَانَ ‏ ‏الْحَسَنُ ‏ ‏يَقُولُ ذَلِكَ ‏","","",""],[799,799,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏سُمَيًّا ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏الْقَعْقَاعَ بْنَ حَكِيمٍ ‏ ‏وَزَيْدَ بْنَ أَسْلَمَ ‏ ‏أَرْسَلَاهُ إِلَى ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏يَسْأَلُهُ كَيْفَ تَغْتَسِلُ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏تَغْتَسِلُ مِنْ الظُّهْرِ إِلَى مِثْلِهَا مِنْ الْغَدِ لِصَلَاةِ الظُّهْرِ فَإِنْ غَلَبَهَا الدَّمُ ‏ ‏اسْتَثْفَرَتْ ‏ ‏وَتَوَضَّأَتْ لِكُلِّ صَلَاةٍ وَصَلَّتْ ‏","","",""],[800,800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُعْتَمِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ مِنْ صَلَاةِ الظُّهْرِ إِلَى صَلَاةِ الظُّهْرِ مِنْ الْغَدِ ‏","","",""]];
